fn tts_input_click_disposition(
    clicked_main_text_input: bool,
    clicked_main_input_container: bool,
    clicked_instruct_input: bool,
) -> TtsInputClickDisposition {
    if clicked_main_text_input || clicked_instruct_input {
        TtsInputClickDisposition::LetInputHandle
    } else if clicked_main_input_container {
        TtsInputClickDisposition::MoveMainCursorToEnd
    } else {
        TtsInputClickDisposition::CollapseSelections
    }
}

fn tts_input_drag_scroll_delta(
    pointer_y: f64,
    container_top: f64,
    container_bottom: f64,
    edge_band: f64,
    max_delta: f64,
) -> f64 {
    if edge_band <= 0.0 || max_delta <= 0.0 || container_bottom <= container_top {
        return 0.0;
    }

    let top_distance = pointer_y - container_top;
    if top_distance <= edge_band {
        let proximity = ((edge_band - top_distance) / edge_band).clamp(0.0, 1.0);
        return -max_delta * proximity;
    }

    let bottom_distance = container_bottom - pointer_y;
    if bottom_distance <= edge_band {
        let proximity = ((edge_band - bottom_distance) / edge_band).clamp(0.0, 1.0);
        return max_delta * proximity;
    }

    0.0
}

fn tts_input_drag_release_should_restore_focus(
    was_drag_selecting_from_input: bool,
    selected_text_len: usize,
) -> bool {
    was_drag_selecting_from_input && selected_text_len > 0
}

fn player_playback_position_after_tick(
    current_secs: f64,
    total_secs: f64,
    tick_secs: f64,
    playback_rate: f64,
) -> f64 {
    if total_secs <= 0.0 {
        return 0.0;
    }
    let media_delta = tick_secs.max(0.0) * playback_rate.max(0.0);
    (current_secs + media_delta).clamp(0.0, total_secs)
}

fn player_effective_volume(volume: f64, muted: bool) -> f64 {
    if muted {
        0.0
    } else {
        volume.clamp(0.0, 1.0)
    }
}

fn player_playback_rate_index(current_rate: f64) -> usize {
    PLAYER_PLAYBACK_RATES
        .iter()
        .position(|rate| (*rate - current_rate).abs() < 0.01)
        .unwrap_or(1)
}

fn player_menu_abs_pos(anchor: Rect, menu_width: f64, menu_height: f64) -> DVec2 {
    dvec2(
        (anchor.pos.x + anchor.size.x - menu_width).max(0.0),
        (anchor.pos.y - menu_height - PLAYER_MENU_ANCHOR_GAP).max(0.0),
    )
}

