    fn normalize_transcript_file_name(input: &str) -> String {
        let trimmed = input.trim();
        let fallback = "transcript.md";
        let raw = if trimmed.is_empty() { fallback } else { trimmed };
        let sanitized: String = raw
            .chars()
            .map(|c| match c {
                '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => '_',
                _ => c,
            })
            .collect();
        let sanitized = sanitized.trim();
        if sanitized.is_empty() {
            fallback.to_string()
        } else if sanitized.to_lowercase().ends_with(".md") {
            sanitized.to_string()
        } else {
            format!("{sanitized}.md")
        }
    }

    fn transcript_default_save_dir() -> PathBuf {
        dirs::home_dir()
            .map(|home| home.join("Downloads"))
            .filter(|path| path.exists())
            .unwrap_or_else(|| PathBuf::from("."))
    }

    fn transcript_save_path_from_preferences(&self) -> PathBuf {
        let dir = self
            .app_preferences
            .translation_transcript_save_dir
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
            .unwrap_or_else(Self::transcript_default_save_dir);
        dir.join(Self::normalize_transcript_file_name(
            &self.app_preferences.translation_transcript_file_name,
        ))
    }

    fn transcript_timestamp() -> String {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_millis().to_string())
            .unwrap_or_else(|_| "0".to_string())
    }

    fn transcript_timestamped_save_path_from_preferences(&self) -> PathBuf {
        let base_path = self.transcript_save_path_from_preferences();
        let timestamp = Self::transcript_timestamp();
        let stem = base_path
            .file_stem()
            .and_then(|value| value.to_str())
            .filter(|value| !value.is_empty())
            .unwrap_or("transcript");
        let extension = base_path
            .extension()
            .and_then(|value| value.to_str())
            .filter(|value| !value.is_empty())
            .unwrap_or("md");
        base_path.with_file_name(format!("{stem}_{timestamp}.{extension}"))
    }

    fn translation_history_snapshot(&self) -> Vec<(String, String)> {
        self.translation_shared_state()
            .and_then(|shared| shared.translation.read())
            .map(|update| {
                update
                    .history
                    .iter()
                    .map(|s| (s.source_text.clone(), s.translation.clone()))
                    .collect()
            })
            .unwrap_or_default()
    }

