    fn apply_tts_history_mode_layout(&mut self, cx: &mut Cx) {
        let history_mode =
            self.current_page == AppPage::TextToSpeech && self.controls_panel_tab == 2;

        let title = if history_mode {
            self.tr("历史", "History")
        } else {
            self.tr("文本转语音", "Text to Speech")
        };
        self.view
            .label(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .page_header
                    .page_title
            ))
            .set_text(cx, title);
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
            ))
            .set_visible(cx, !history_mode);

        // Hide audio player bar when in History mode
        let show_player =
            self.has_generated_audio && !history_mode && self.current_page == AppPage::TextToSpeech;
        self.view
            .view(ids!(content_wrapper.audio_player_bar))
            .set_visible(cx, show_player);

        if history_mode {
            self.view
                .view(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .controls_panel
                ))
                .apply_over(cx, live! { width: Fill });
        } else {
            self.view
                .view(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .controls_panel
                ))
                .apply_over(cx, live! { width: 320 });
        }
    }

    fn update_sidebar_nav_states(&mut self, cx: &mut Cx) {
        let tts_context = self.current_page == AppPage::TextToSpeech;
        let tts_active = if tts_context && self.controls_panel_tab != 2 {
            1.0
        } else {
            0.0
        };
        let history_active = if tts_context && self.controls_panel_tab == 2 {
            1.0
        } else {
            0.0
        };
        let library_active = if self.current_page == AppPage::VoiceLibrary {
            1.0
        } else {
            0.0
        };
        let clone_active = if self.current_page == AppPage::VoiceClone
            || self.current_page == AppPage::TaskDetail
        {
            1.0
        } else {
            0.0
        };
        let user_settings_active = if self.current_page == AppPage::UserSettings {
            1.0
        } else {
            0.0
        };
        let translation_active = if self.current_page == AppPage::Translation {
            1.0
        } else {
            0.0
        };
        let about_active = if self.current_page == AppPage::About {
            1.0
        } else {
            0.0
        };

        self.view
            .button(ids!(app_layout.sidebar.sidebar_nav.nav_tts))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (tts_active) }
                    draw_text: { active: (tts_active) }
                },
            );
        self.view
            .button(ids!(app_layout.sidebar.sidebar_nav.nav_history))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (history_active) }
                    draw_text: { active: (history_active) }
                },
            );
        self.view
            .button(ids!(app_layout.sidebar.sidebar_nav.nav_library))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (library_active) }
                    draw_text: { active: (library_active) }
                },
            );
        self.view
            .button(ids!(app_layout.sidebar.sidebar_nav.nav_clone))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (clone_active) }
                    draw_text: { active: (clone_active) }
                },
            );
        self.view
            .button(ids!(app_layout.sidebar.sidebar_nav.nav_translation))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (translation_active) }
                    draw_text: { active: (translation_active) }
                },
            );
        self.view
            .button(ids!(app_layout.sidebar.sidebar_nav.nav_about))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (about_active) }
                    draw_text: { active: (about_active) }
                },
            );
        self.view
            .view(ids!(app_layout.sidebar.sidebar_footer))
            .apply_over(cx, live! { draw_bg: { active: (user_settings_active) } });
    }

    /// Switch to a different page and update UI accordingly
    fn switch_page(&mut self, cx: &mut Cx, page: AppPage) {
        if self.current_page == page {
            self.update_sidebar_nav_states(cx);
            return; // Already on this page
        }

        // Floating player menus are root overlays. Close them while their player-bar
        // anchors are still laid out, before switching away from the TTS page.
        self.player_speed_menu_open = false;
        self.player_action_menu_open = false;
        self.player_segment_menu_open = false;
        self.update_player_menu_visibility(cx);

        self.current_page = page;
        self.add_log(cx, &format!("[INFO] [ui] Switching to {:?} page", page));
        self.update_sidebar_nav_states(cx);

        // Show/hide page content based on current_page
        let show_tts = page == AppPage::TextToSpeech;
        let show_library = page == AppPage::VoiceLibrary;
        let show_clone = page == AppPage::VoiceClone;
        let show_detail = page == AppPage::TaskDetail;
        let show_user_settings = page == AppPage::UserSettings;
        let show_translation = page == AppPage::Translation;
        let show_about = page == AppPage::About;

        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
            ))
            .set_visible(cx, show_tts);

        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .library_page
            ))
            .set_visible(cx, show_library);

        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .clone_page
            ))
            .set_visible(cx, show_clone);

        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .task_detail_page
            ))
            .set_visible(cx, show_detail);
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .user_settings_page
            ))
            .set_visible(cx, show_user_settings);
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .translation_page
            ))
            .set_visible(cx, show_translation);
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .about_page
            ))
            .set_visible(cx, show_about);

        // Show audio player bar only on TTS page (not History tab) after first successful generation
        let history_mode = show_tts && self.controls_panel_tab == 2;
        self.view
            .view(ids!(content_wrapper.audio_player_bar))
            .set_visible(cx, show_tts && self.has_generated_audio && !history_mode);

        if show_library {
            self.update_library_display(cx);
        }
        if show_user_settings {
            self.update_user_settings_page(cx);
            self.update_user_settings_tabs(cx);
        }

        // The translation overlay window stays open until the user explicitly
        // closes it — no auto-hide on page navigation.

        self.apply_tts_history_mode_layout(cx);
        self.view.redraw(cx);
    }

