    fn update_generation_status(&mut self, cx: &mut Cx) {
        let show = self.tts_status == TTSStatus::Generating
            && self.pending_generation_expected_segments > 0;
        let received = self.pending_generation_received_segments;
        let expected = self.pending_generation_expected_segments.max(1);
        let current = if expected > 1 {
            (received + 1).min(expected)
        } else {
            1
        };
        let label = if self.is_english() {
            format!("Generating segment {}/{}...", current, expected)
        } else {
            format!("正在生成 {}/{}...", current, expected)
        };

        self.view
            .label(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
                    .input_content
                    .bottom_bar
                    .action_row
                    .status_stack
                    .generation_status
            ))
            .set_text(cx, if show { label.as_str() } else { "" });
        if show {
            self.view
                .view(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                        .bottom_bar
                        .action_row
                        .status_stack
                ))
                .apply_over(cx, live! { spacing: 2 });
            self.view
                .label(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                        .bottom_bar
                        .action_row
                        .status_stack
                        .generation_status
                ))
                .apply_over(cx, live! { height: Fit });
        } else {
            self.view
                .view(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                        .bottom_bar
                        .action_row
                        .status_stack
                ))
                .apply_over(cx, live! { spacing: 0 });
            self.view
                .label(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                        .bottom_bar
                        .action_row
                        .status_stack
                        .generation_status
                ))
                .apply_over(cx, live! { height: 0 });
        }
    }

    fn send_next_pending_tts_segment(&mut self, cx: &mut Cx) -> bool {
        let Some(voice_id) = self.pending_generation_voice_id.clone() else {
            self.add_log(cx, "[ERROR] [tts] Missing pending voice for generation segment");
            return false;
        };
        let Some((segment_number, total_segments, segment)) =
            self.pending_generation_dispatch.take_next()
        else {
            return true;
        };

        let voice_info = self
            .library_voices
            .iter()
            .find(|voice| voice.id == voice_id)
            .cloned();
        let prompt = self.build_tts_prompt_for_segment(&voice_id, voice_info.as_ref(), &segment);
        let prompt_preview = if prompt.chars().count() > 100 {
            let end: usize = prompt
                .char_indices()
                .nth(100)
                .map(|(i, _)| i)
                .unwrap_or(prompt.len());
            format!("{}...", &prompt[..end])
        } else {
            prompt.clone()
        };
        self.add_log(
            cx,
            &format!(
                "[DEBUG] Sending prompt segment {}/{}: {}",
                segment_number, total_segments, prompt_preview
            ),
        );

        let payload = serde_json::json!({
            "prompt": prompt,
            "speed": self.pending_generation_speed,
            "pitch": self.pending_generation_pitch,
            "volume": self.pending_generation_volume,
            "emotion": self.pending_generation_emotion_id.clone(),
            "instruct": self.pending_generation_instruct.clone(),
        });
        let payload_text = payload.to_string();
        let segment_index = segment_number.saturating_sub(1);
        let Some(pending_segment) = self.pending_tts_segments.get_mut(segment_index) else {
            self.add_log(
                cx,
                &format!(
                    "[ERROR] [tts] Missing pending audio segment {}/{}",
                    segment_number, total_segments
                ),
            );
            return false;
        };
        pending_segment.request_payload = payload_text.clone();
        self.active_tts_segment = Some(ActiveSegmentAssembly::new(segment_index));
        self.active_tts_operation = Some(ActiveTtsOperation::Initial);
        let sent = self
            .dora
            .as_ref()
            .map(|d| d.send_prompt(&payload_text))
            .unwrap_or(false);
        if !sent {
            self.add_log(
                cx,
                &format!(
                    "[ERROR] [tts] Failed to send prompt segment {}/{} to Dora",
                    segment_number, total_segments
                ),
            );
            self.active_tts_segment = None;
            self.active_tts_operation = None;
        }
        sent
    }

    fn rebuild_audio_from_tts_segments(&mut self) {
        let Some(segments) = self.tts_audio_segments.as_ref() else {
            return;
        };
        self.playback_audio_source = Some(PlaybackAudioSource::from_segments(segments.clone()));
        self.playback_feed_cursor = 0;
        self.playback_feed_finished = false;
    }

    fn finalize_active_initial_tts_segment(&mut self, cx: &mut Cx) {
        let Some(active) = self.active_tts_segment.take() else {
            self.fail_pending_tts_generation(cx, "[ERROR] [tts] Missing active TTS segment");
            return;
        };
        let segment_index = active.index;
        let (samples, sample_rate) = match active.into_samples() {
            Ok(audio) => audio,
            Err(error) => {
                self.fail_pending_tts_generation(
                    cx,
                    &format!("[ERROR] [tts] Invalid segment audio: {error:?}"),
                );
                return;
            }
        };
        let expected_rate = self
            .pending_tts_segments
            .iter()
            .find(|segment| segment.sample_rate != 0)
            .map(|segment| segment.sample_rate);
        if let Some(expected_rate) = expected_rate {
            if expected_rate != sample_rate {
                self.fail_pending_tts_generation(
                    cx,
                    &format!(
                        "[ERROR] [tts] Segment sample rate mismatch: expected {}, got {}",
                        expected_rate, sample_rate
                    ),
                );
                return;
            }
        }
        let Some(segment) = self.pending_tts_segments.get_mut(segment_index) else {
            self.fail_pending_tts_generation(cx, "[ERROR] [tts] Missing pending TTS segment");
            return;
        };
        segment.samples = Arc::new(samples);
        segment.sample_rate = sample_rate;

        self.pending_generation_dispatch.mark_received();
        self.pending_generation_received_segments = self.pending_generation_dispatch.received;
        self.update_generation_status(cx);
        if !self.pending_generation_dispatch.is_complete() {
            if !self.send_next_pending_tts_segment(cx) {
                self.fail_pending_tts_generation(
                    cx,
                    "[ERROR] [tts] Failed to send next prompt segment to Dora",
                );
            }
            return;
        }

        let completed_segments = std::mem::take(&mut self.pending_tts_segments);
        let segments = match TtsAudioSegments::new(completed_segments) {
            Ok(segments) => segments,
            Err(error) => {
                self.fail_pending_tts_generation(
                    cx,
                    &format!("[ERROR] [tts] Failed to publish audio segments: {error:?}"),
                );
                return;
            }
        };
        self.tts_audio_segments = Some(segments);
        self.rebuild_audio_from_tts_segments();
        let sample_count = self.playback_audio_total_samples();
        let effective_rate = self.playback_audio_sample_rate();
        let duration_secs = if effective_rate > 0 {
            sample_count as f32 / effective_rate as f32
        } else {
            0.0
        };
        self.add_log(
            cx,
            &format!(
                "[INFO] [tts] Audio generated: {} samples, {:.1}s duration",
                sample_count, duration_secs
            ),
        );
        self.tts_status = TTSStatus::Ready;
        self.audio_playing_time = 0.0;
        self.has_generated_audio = true;
        let generated_voice_id = self
            .pending_generation_voice_id
            .clone()
            .or_else(|| self.selected_voice_id.clone());
        if let Some(voice_id) = generated_voice_id {
            self.apply_generated_voice_to_player_bar(cx, &voice_id, None);
        }
        self.append_current_generation_to_history(cx);
        self.clear_pending_generation_snapshot();
        self.set_generate_button_loading(cx, false);
        self.update_player_bar(cx);
    }

    fn fail_active_tts_retry(&mut self, cx: &mut Cx, message: &str) {
        self.active_tts_segment = None;
        self.active_tts_operation = None;
        self.tts_status = TTSStatus::Ready;
        self.set_generate_button_loading(cx, false);
        self.add_log(cx, message);
        self.show_toast(
            cx,
            self.tr("分段重试失败，可再次重试", "Segment retry failed; try again"),
        );
        self.update_player_bar(cx);
    }

    fn finalize_active_tts_retry(&mut self, cx: &mut Cx) {
        let Some(active) = self.active_tts_segment.take() else {
            self.fail_active_tts_retry(cx, "[ERROR] [tts] Missing active retry segment");
            return;
        };
        let segment_index = active.index;
        let (samples, sample_rate) = match active.into_samples() {
            Ok(audio) => audio,
            Err(error) => {
                self.fail_active_tts_retry(
                    cx,
                    &format!("[ERROR] [tts] Invalid retry audio: {error:?}"),
                );
                return;
            }
        };
        let Some(segments) = self.tts_audio_segments.as_mut() else {
            self.fail_active_tts_retry(cx, "[ERROR] [tts] No audio segments available to retry");
            return;
        };
        if let Err(error) = segments.apply_retry(
            segment_index,
            RetryCommit::Replace {
                samples,
                sample_rate,
            },
        ) {
            self.fail_active_tts_retry(
                cx,
                &format!("[ERROR] [tts] Failed to replace retry segment: {error:?}"),
            );
            return;
        }
        let start_time = segments.start_time_secs(segment_index).unwrap_or(0.0);
        self.active_tts_operation = None;
        self.rebuild_audio_from_tts_segments();
        self.tts_status = TTSStatus::Ready;
        self.set_generate_button_loading(cx, false);
        if self.start_playback_from_time(cx, start_time) {
            self.add_log(
                cx,
                &format!(
                    "[INFO] [tts] Replaced segment {} and started playback at {:.1}s",
                    segment_index + 1,
                    start_time
                ),
            );
        }
        self.update_player_bar(cx);
    }

    fn retry_tts_segment(&mut self, cx: &mut Cx, segment_index: usize) {
        if self.tts_status == TTSStatus::Generating {
            return;
        }
        let Some(payload) = self
            .tts_audio_segments
            .as_ref()
            .and_then(|segments| segments.segment(segment_index))
            .map(|segment| segment.request_payload.clone())
        else {
            self.show_toast(cx, self.tr("找不到音频分段", "Audio segment not found"));
            return;
        };
        if payload.is_empty() {
            self.show_toast(
                cx,
                self.tr("该分段没有可重试的请求", "This segment has no retry request"),
            );
            return;
        }
        if self.dora.is_none() {
            self.show_toast(cx, self.tr("TTS 引擎未就绪", "TTS engine is not ready"));
            return;
        }
        self.stop_preview_playback(cx);
        if let Some(player) = &self.audio_player {
            player.stop();
        }
        self.active_tts_segment = Some(ActiveSegmentAssembly::new(segment_index));
        self.active_tts_operation = Some(ActiveTtsOperation::Retry);
        self.tts_status = TTSStatus::Generating;
        self.set_generate_button_loading(cx, true);
        let dora = self.dora.as_ref().expect("Dora availability was checked");
        let _ = dora.shared_dora_state().audio.drain();
        dora.shared_dora_state().tts_segment_events.clear();
        if !dora.send_prompt(payload) {
            self.fail_active_tts_retry(cx, "[ERROR] [tts] Failed to send segment retry to Dora");
            return;
        }
        self.update_player_bar(cx);
    }

    fn preview_tts_segment(&mut self, cx: &mut Cx, segment_index: usize) {
        if self.tts_status == TTSStatus::Generating {
            return;
        }
        let preview_id = format!("tts-segment-{}", segment_index);
        if self.preview_playing_voice_id.as_deref() == Some(preview_id.as_str()) {
            if self.segment_preview_playing {
                if let Some(player) = &self.preview_player {
                    player.pause();
                }
                self.segment_preview_playing = false;
                self.add_log(
                    cx,
                    &format!("[INFO] [tts] Paused segment {}", segment_index + 1),
                );
            } else {
                self.stop_main_playback_for_preview(cx);
                if let Some(player) = &self.preview_player {
                    player.resume();
                }
                self.segment_preview_playing = true;
                self.add_log(
                    cx,
                    &format!("[INFO] [tts] Resumed segment {}", segment_index + 1),
                );
            }
            self.update_player_bar(cx);
            self.view.redraw(cx);
            return;
        }
        let Some((samples, sample_rate)) = self
            .tts_audio_segments
            .as_ref()
            .and_then(|segments| segments.segment(segment_index))
            .map(|segment| (segment.samples.clone(), segment.sample_rate))
        else {
            self.show_toast(cx, self.tr("找不到音频分段", "Audio segment not found"));
            return;
        };
        if samples.is_empty() || sample_rate == 0 {
            self.show_toast(cx, self.tr("该分段没有音频", "This segment has no audio"));
            return;
        }
        self.stop_main_playback_for_preview(cx);
        if let Some(player) = &self.preview_player {
            player.stop();
        }
        let player = TTSPlayer::new_with_output_device(
            sample_rate,
            self.app_preferences.preferred_output_device.as_deref(),
        );
        self.preview_player = Some(player);
        self.preview_audio_source = Some(PlaybackAudioSource::from_contiguous(
            samples,
            sample_rate,
            sample_rate,
        ));
        self.preview_feed_cursor = 0;
        self.preview_feed_finished = false;
        self.fill_preview_queue(0);
        if self.preview_feed_cursor == 0 {
            self.preview_audio_source = None;
            self.preview_feed_finished = true;
            return;
        }
        self.preview_playing_voice_id = Some(preview_id);
        self.segment_preview_playing = true;
        self.add_log(
            cx,
            &format!("[INFO] [tts] Previewing segment {}", segment_index + 1),
        );
        self.update_player_bar(cx);
        self.view.redraw(cx);
    }

    fn fail_pending_tts_generation(&mut self, cx: &mut Cx, message: &str) {
        self.add_log(cx, message);
        self.clear_pending_generation_snapshot();
        self.tts_status = TTSStatus::Error(message.to_string());
        self.set_generate_button_loading(cx, false);
        self.update_player_bar(cx);
    }

    fn set_generate_button_loading(&mut self, cx: &mut Cx, loading: bool) {
        let selected_voice_is_trained = self
            .selected_voice_id
            .as_ref()
            .and_then(|id| self.library_voices.iter().find(|v| &v.id == id))
            .map(|voice| voice.source == crate::voice_data::VoiceSource::Trained)
            .unwrap_or(false);
        let trained_voice_supported =
            !(Self::is_qwen_backend(&self.app_preferences.inference_backend)
                && selected_voice_is_trained);

        // Update button text
        let button_text = if loading {
            self.tr("生成中...", "Generating...")
        } else if !trained_voice_supported {
            self.tr(
                "Qwen 暂不支持训练音色",
                "Qwen does not support trained voices",
            )
        } else {
            self.tr("生成语音", "Generate Speech")
        };
        self.view
            .button(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
                    .input_content
                    .bottom_bar
                    .action_row
                    .generate_section
                    .generate_btn
            ))
            .set_text(cx, button_text);
        self.view
            .button(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
                    .input_content
                    .bottom_bar
                    .action_row
                    .generate_section
                    .generate_btn
            ))
            .set_enabled(cx, !loading && trained_voice_supported);

        // Show/hide spinner
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
                    .input_content
                    .bottom_bar
                    .action_row
                    .generate_spinner
            ))
            .set_visible(cx, loading);

        // Start/stop spinner animation
        if loading {
            self.view
                .view(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                        .bottom_bar
                        .action_row
                        .generate_spinner
                ))
                .animator_play(cx, ids!(spin.on));
        } else {
            self.view
                .view(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                        .bottom_bar
                        .action_row
                        .generate_spinner
                ))
                .animator_play(cx, ids!(spin.off));
        }

        self.update_generation_status(cx);
        self.view.redraw(cx);
    }

    fn clear_pending_generation_snapshot(&mut self) {
        self.pending_generation_voice_id = None;
        self.pending_generation_text = None;
        self.pending_generation_model_id = None;
        self.pending_generation_model_name = None;
        self.pending_generation_speed = self.tts_speed;
        self.pending_generation_pitch = self.tts_pitch;
        self.pending_generation_volume = self.tts_volume;
        self.pending_generation_emotion_id = None;
        self.pending_generation_emotion_label = None;
        self.pending_generation_instruct = None;
        self.pending_generation_expected_segments = 0;
        self.pending_generation_received_segments = 0;
        self.pending_generation_dispatch.clear();
        self.pending_tts_segments.clear();
        self.active_tts_segment = None;
        self.active_tts_operation = None;
    }

    fn update_audio_player_visibility(&mut self, cx: &mut Cx) {
        let history_mode =
            self.current_page == AppPage::TextToSpeech && self.controls_panel_tab == 2;
        let show_player =
            self.current_page == AppPage::TextToSpeech && self.has_generated_audio && !history_mode;
        self.view
            .view(ids!(content_wrapper.audio_player_bar))
            .set_visible(cx, show_player);
    }

    fn set_player_bar_voice_labels(&mut self, cx: &mut Cx, voice_name: &str) {
        let initial = voice_name.chars().next().unwrap_or('?').to_string();
        self.current_voice_name = voice_name.to_string();

        self.view
            .label(ids!(
                content_wrapper
                    .audio_player_bar
                    .voice_info
                    .voice_name_container
                    .voice_name_clip
                    .current_voice_name
            ))
            .set_text(cx, voice_name);
        self.view
            .label(ids!(
                content_wrapper
                    .audio_player_bar
                    .voice_info
                    .voice_avatar
                    .avatar_initial
            ))
            .set_text(cx, &initial);
    }

    fn apply_voice_to_player_bar(
        &mut self,
        cx: &mut Cx,
        voice_id: &str,
        fallback_name: Option<&str>,
    ) {
        let voice_name = self
            .library_voices
            .iter()
            .find(|v| v.id == voice_id)
            .map(|v| v.name.clone())
            .or_else(|| fallback_name.map(|s| s.to_string()))
            .unwrap_or_else(|| voice_id.to_string());
        self.set_player_bar_voice_labels(cx, &voice_name);
    }

    fn apply_generated_voice_to_player_bar(
        &mut self,
        cx: &mut Cx,
        voice_id: &str,
        fallback_name: Option<&str>,
    ) {
        self.generated_voice_id = Some(voice_id.to_string());
        self.apply_voice_to_player_bar(cx, voice_id, fallback_name);
    }

    fn update_player_bar(&mut self, cx: &mut Cx) {
        self.update_audio_player_visibility(cx);

        self.view
            .label(ids!(player_segment_menu.segment_header.segment_title))
            .set_text(cx, self.tr("音频分段", "Audio Segments"));

        // Update status label
        let status_text = match self.tts_status {
            TTSStatus::Idle => self.tr("就绪", "Ready"),
            TTSStatus::Generating => self.tr("生成中...", "Generating..."),
            TTSStatus::Playing => self.tr("播放中", "Playing"),
            TTSStatus::Ready => self.tr("音频已生成", "Audio Ready"),
            TTSStatus::Error(ref msg) => msg.as_str(),
        };
        self.view
            .label(ids!(
                content_wrapper
                    .audio_player_bar
                    .voice_info
                    .voice_name_container
                    .status_label
            ))
            .set_text(cx, status_text);

        let audio_len = self.playback_audio_total_samples();
        let effective_rate = self.playback_audio_sample_rate();
        let has_playable_audio = self.has_generated_audio && audio_len > 0 && effective_rate > 0;
        let is_english = self.is_english();
        let segment_summary = self
            .tts_audio_segments
            .as_ref()
            .map(|segments| {
                let duration = if effective_rate > 0 {
                    audio_len as f32 / effective_rate as f32
                } else {
                    0.0
                };
                let count = if is_english {
                    format!("{} segments", segments.len())
                } else {
                    format!("{} 段", segments.len())
                };
                format!("{} · {}", count, Self::format_duration(duration))
            })
            .unwrap_or_default();
        self.view
            .label(ids!(player_segment_menu.segment_header.segment_summary))
            .set_text(cx, &segment_summary);
        let controls_enabled = has_playable_audio && self.tts_status != TTSStatus::Generating;
        if !controls_enabled {
            self.player_speed_menu_open = false;
            self.player_action_menu_open = false;
            self.player_segment_menu_open = false;
        }

        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .action_buttons_row
                    .segment_menu_btn
            ))
            .set_enabled(cx, controls_enabled && self.tts_audio_segments.is_some());
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .playback_controls
                    .controls_row
                    .play_btn
            ))
            .set_enabled(cx, controls_enabled);
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .mute_btn
            ))
            .set_enabled(cx, controls_enabled);
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .speed_menu_btn
            ))
            .set_enabled(cx, controls_enabled);
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .action_buttons_row
                    .action_menu_btn
            ))
            .set_enabled(cx, controls_enabled);

        // Update play button state
        let is_playing = self.tts_status == TTSStatus::Playing;
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .playback_controls
                    .controls_row
                    .play_btn
            ))
            .apply_over(
                cx,
                live! {
                    draw_bg: { is_playing: (if is_playing { 1.0 } else { 0.0 }) }
                },
            );
        self.update_player_setting_labels(cx);

        // Update total time
        if has_playable_audio {
            let duration_secs = audio_len as f32 / effective_rate as f32;
            let mins = (duration_secs / 60.0) as u32;
            let secs = (duration_secs % 60.0) as u32;
            let time_str = format!("{:02}:{:02}", mins, secs);
            self.view
                .label(ids!(
                    content_wrapper
                        .audio_player_bar
                        .playback_controls
                        .progress_row
                        .total_time
                ))
                .set_text(cx, &time_str);
        } else {
            self.view
                .label(ids!(
                    content_wrapper
                        .audio_player_bar
                        .playback_controls
                        .progress_row
                        .current_time
                ))
                .set_text(cx, "00:00");
            self.view
                .label(ids!(
                    content_wrapper
                        .audio_player_bar
                        .playback_controls
                        .progress_row
                        .total_time
                ))
                .set_text(cx, "00:00");
            self.view
                .view(ids!(
                    content_wrapper
                        .audio_player_bar
                        .playback_controls
                        .progress_row
                        .progress_bar_container
                        .progress_bar
                ))
                .apply_over(
                    cx,
                    live! {
                        draw_bg: { progress: 0.0 }
                    },
                );
        }

        self.view.redraw(cx);
    }

    fn player_rate_label(rate: f64) -> String {
        let rounded_hundredths = (rate * 100.0).round() as i32;
        if rounded_hundredths % 100 == 0 {
            format!("{}x", rounded_hundredths / 100)
        } else if rounded_hundredths % 10 == 0 {
            format!("{:.1}x", rounded_hundredths as f64 / 100.0)
        } else {
            format!("{:.2}x", rounded_hundredths as f64 / 100.0)
        }
    }

    fn update_player_setting_labels(&mut self, cx: &mut Cx) {
        let effective_volume = player_effective_volume(self.player_volume, self.player_muted);
        let speed_idx = player_playback_rate_index(self.player_playback_rate);
        let speed_label = Self::player_rate_label(self.player_playback_rate);

        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .mute_btn
            ))
            .apply_over(
                cx,
                live! {
                    draw_bg: { muted: (if self.player_muted { 1.0 } else { 0.0 }) }
                },
            );
        self.view
            .view(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .volume_slider_container
                    .volume_slider
            ))
            .apply_over(
                cx,
                live! {
                    draw_bg: { progress: (effective_volume) }
                },
            );
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .speed_menu_btn
            ))
            .set_text(cx, &speed_label);
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .speed_menu_btn
            ))
            .apply_over(
                cx,
                live! {
                    draw_bg: { active: (if self.player_speed_menu_open { 1.0 } else { 0.0 }) }
                },
            );
        self.view
            .button(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .action_buttons_row
                    .action_menu_btn
            ))
            .apply_over(
                cx,
                live! {
                    draw_bg: { dark_mode: (self.dark_mode) active: 1.0 }
                },
            );
        for (idx, path) in [
            (0, ids!(player_speed_menu.speed_075_btn)),
            (1, ids!(player_speed_menu.speed_100_btn)),
            (2, ids!(player_speed_menu.speed_125_btn)),
            (3, ids!(player_speed_menu.speed_150_btn)),
            (4, ids!(player_speed_menu.speed_200_btn)),
        ] {
            self.view.button(path).apply_over(
                cx,
                live! {
                    draw_bg: { active: (if speed_idx == idx { 1.0 } else { 0.0 }) }
                    draw_text: { active: (if speed_idx == idx { 1.0 } else { 0.0 }) }
                },
            );
        }
        self.update_player_menu_visibility(cx);
    }

    fn apply_player_audio_settings(&self) {
        if let Some(player) = &self.audio_player {
            player.set_volume(player_effective_volume(
                self.player_volume,
                self.player_muted,
            ));
            // Playback speed is applied by preparing time-stretched samples before
            // writing to the player. Keep the realtime player at 1x to preserve pitch.
            player.set_playback_rate(1.0);
        }
    }

    fn toggle_player_mute(&mut self, cx: &mut Cx) {
        self.player_muted = !self.player_muted;
        self.apply_player_audio_settings();
        self.update_player_bar(cx);
    }

    fn set_player_volume_from_ratio(&mut self, cx: &mut Cx, ratio: f64) {
        self.player_volume = ratio.clamp(0.0, 1.0);
        self.player_muted = self.player_volume <= 0.0;
        self.apply_player_audio_settings();
        self.update_player_bar(cx);
    }

