    fn set_player_playback_rate(&mut self, cx: &mut Cx, rate: f64) {
        self.player_playback_rate = rate;
        if self.tts_status == TTSStatus::Playing {
            let _ = self.start_playback_from_time(cx, self.audio_playing_time);
        } else {
            self.begin_playback_stretch_task();
            self.apply_player_audio_settings();
        }
        self.update_player_bar(cx);
    }

    fn format_duration(duration_secs: f32) -> String {
        let total = duration_secs.max(0.0).round() as u32;
        let mins = total / 60;
        let secs = total % 60;
        format!("{:02}:{:02}", mins, secs)
    }

    fn format_history_time(&self, created_at: u64) -> String {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(created_at);
        let diff = now.saturating_sub(created_at);

        if self.is_english() {
            if diff < 60 {
                "Just now".to_string()
            } else if diff < 3600 {
                format!("{}m ago", diff / 60)
            } else if diff < 86400 {
                format!("{}h ago", diff / 3600)
            } else {
                format!("{}d ago", diff / 86400)
            }
        } else if diff < 60 {
            "刚刚".to_string()
        } else if diff < 3600 {
            format!("{} 分钟前", diff / 60)
        } else if diff < 86400 {
            format!("{} 小时前", diff / 3600)
        } else {
            format!("{} 天前", diff / 86400)
        }
    }

    fn history_text_preview(text: &str) -> String {
        let trimmed = text.trim();
        if trimmed.is_empty() {
            return String::new();
        }
        let max_chars = 90usize;
        if trimmed.chars().count() <= max_chars {
            trimmed.to_string()
        } else {
            let cutoff = trimmed
                .char_indices()
                .nth(max_chars)
                .map(|(idx, _)| idx)
                .unwrap_or(trimmed.len());
            format!("{}...", &trimmed[..cutoff])
        }
    }

    fn persist_tts_history(&mut self, cx: &mut Cx) {
        if let Err(e) = tts_history::save_history(&self.tts_history) {
            self.add_log(
                cx,
                &format!("[WARN] [history] Failed to save history: {}", e),
            );
        }
    }

    fn append_current_generation_to_history(&mut self, cx: &mut Cx) {
        let Some(source) = self.playback_audio_source.clone() else {
            return;
        };
        let sample_count = source.total_samples();
        let effective_rate = source.sample_rate();
        if sample_count == 0 || effective_rate == 0 {
            return;
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default();
        let created_at = now.as_secs();
        let entry_id = format!("gen-{}-{}", created_at, now.subsec_nanos());
        let audio_file = format!("{}.wav", entry_id);
        let audio_path = tts_history::history_audio_path(&audio_file);

        if let Err(e) = tts_history::ensure_history_storage() {
            self.add_log(
                cx,
                &format!("[WARN] [history] Failed to prepare storage: {}", e),
            );
            return;
        }
        if let Err(e) = Self::write_wav_file_from_source(&audio_path, &source) {
            self.add_log(
                cx,
                &format!("[WARN] [history] Failed to save audio snapshot: {}", e),
            );
            return;
        }

        let voice_id = self
            .pending_generation_voice_id
            .clone()
            .or_else(|| self.selected_voice_id.clone())
            .unwrap_or_else(|| "unknown".to_string());
        let voice_name = self
            .library_voices
            .iter()
            .find(|v| v.id == voice_id)
            .map(|v| v.name.clone())
            .unwrap_or_else(|| self.current_voice_name.clone());

        let text = self.pending_generation_text.clone().unwrap_or_else(|| {
            self.view
                .text_input(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                    .input_container
                        .text_input
                ))
                .text()
        });

        let duration_secs = sample_count as f32 / effective_rate as f32;
        let entry = TtsHistoryEntry {
            id: entry_id,
            created_at,
            text: text.clone(),
            text_preview: Self::history_text_preview(&text),
            voice_id,
            voice_name,
            model_id: self.pending_generation_model_id.clone(),
            model_name: self.pending_generation_model_name.clone(),
            duration_secs,
            sample_rate: effective_rate,
            sample_count,
            speed: self.pending_generation_speed,
            pitch: self.pending_generation_pitch,
            volume: self.pending_generation_volume,
            emotion_id: self.pending_generation_emotion_id.clone(),
            emotion_label: self.pending_generation_emotion_label.clone(),
            instruct: self.pending_generation_instruct.clone(),
            audio_file,
        };

        self.tts_history.insert(0, entry);

        if self.tts_history.len() > tts_history::DEFAULT_MAX_HISTORY_ITEMS {
            let removed = self
                .tts_history
                .split_off(tts_history::DEFAULT_MAX_HISTORY_ITEMS);
            for old in removed {
                let _ = tts_history::delete_audio_file(&old.audio_file);
            }
        }

        self.persist_tts_history(cx);
        self.update_history_display(cx);
    }

    fn update_history_display(&mut self, cx: &mut Cx) {
        let count = self.tts_history.len();
        let is_empty = count == 0;
        let count_text = if self.is_english() {
            format!("{} item{}", count, if count == 1 { "" } else { "s" })
        } else {
            format!("{} 条记录", count)
        };

        self.view
            .label(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .controls_panel
                    .history_panel
                    .history_header
                    .history_count
            ))
            .set_text(cx, &count_text);
        self.view
            .button(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .controls_panel
                    .history_panel
                    .history_header
                    .clear_history_btn
            ))
            .set_text(cx, self.tr("清空", "Clear"));
        self.view
            .button(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .controls_panel
                    .history_panel
                    .history_header
                    .clear_history_btn
            ))
            .set_visible(cx, !is_empty);
        self.view
            .portal_list(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .controls_panel
                    .history_panel
                    .history_list
            ))
            .set_visible(cx, !is_empty);
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .controls_panel
                    .history_panel
                    .history_empty
            ))
            .set_visible(cx, is_empty);
        self.view.redraw(cx);
    }

    fn play_history_entry(&mut self, cx: &mut Cx, entry_id: &str) {
        let same_entry = self.currently_playing_history_id.as_deref() == Some(entry_id);
        if same_entry && self.tts_status == TTSStatus::Playing {
            self.toggle_playback(cx);
            self.view.redraw(cx);
            return;
        }
        if same_entry && self.has_generated_audio && self.tts_status == TTSStatus::Ready {
            self.toggle_playback(cx);
            self.view.redraw(cx);
            return;
        }

        self.load_history_entry_into_player(cx, entry_id);
        if self.tts_status == TTSStatus::Ready && self.has_generated_audio {
            self.audio_playing_time = 0.0;
            self.currently_playing_history_id = Some(entry_id.to_string());
            self.toggle_playback(cx);
            self.view.redraw(cx);
        }
    }

    fn load_history_entry_into_player(&mut self, cx: &mut Cx, entry_id: &str) {
        if self.tts_status == TTSStatus::Generating {
            self.show_toast(
                cx,
                self.tr(
                    "生成中，请稍候再操作历史记录",
                    "Generation in progress, please wait",
                ),
            );
            return;
        }

        let entry = match self.tts_history.iter().find(|h| h.id == entry_id).cloned() {
            Some(v) => v,
            None => return,
        };

        let audio_path = tts_history::history_audio_path(&entry.audio_file);
        if !audio_path.exists() {
            self.add_log(
                cx,
                &format!(
                    "[WARN] [history] Audio file missing for entry {}: {:?}",
                    entry.id, audio_path
                ),
            );
            self.show_toast(
                cx,
                self.tr("历史音频文件不存在", "History audio file not found"),
            );
            return;
        }

        if let Some(player) = &self.audio_player {
            player.stop();
        }

        match self.load_wav_mono_file(&audio_path) {
            Ok((samples, sample_rate)) => {
                self.playback_audio_source = Some(PlaybackAudioSource::from_contiguous(
                    Arc::new(samples),
                    sample_rate,
                    24_000,
                ));
                self.playback_feed_cursor = 0;
                self.playback_feed_finished = false;
                self.tts_audio_segments = None;
                self.player_segment_menu_open = false;
                self.audio_playing_time = 0.0;
                self.tts_status = TTSStatus::Ready;
                self.has_generated_audio = true;

                self.apply_generated_voice_to_player_bar(
                    cx,
                    &entry.voice_id,
                    Some(&entry.voice_name),
                );
                self.update_playback_progress(cx);
                self.update_player_bar(cx);
                self.add_log(
                    cx,
                    &format!("[INFO] [history] Loaded entry for playback: {}", entry.id),
                );
            }
            Err(e) => {
                self.add_log(
                    cx,
                    &format!(
                        "[ERROR] [history] Failed to load audio for {}: {}",
                        entry.id, e
                    ),
                );
                self.show_toast(
                    cx,
                    self.tr("加载历史音频失败", "Failed to load history audio"),
                );
            }
        }
    }

    fn reuse_history_entry(&mut self, cx: &mut Cx, entry_id: &str) {
        let entry = match self.tts_history.iter().find(|h| h.id == entry_id).cloned() {
            Some(v) => v,
            None => return,
        };

        self.view
            .text_input(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
                    .input_content
                    .input_container
                    .text_input
            ))
            .set_text(cx, &entry.text);
        self.update_char_count(cx);

        if let Some(voice) = self
            .library_voices
            .iter()
            .find(|v| v.id == entry.voice_id)
            .cloned()
        {
            self.select_voice(cx, voice);
        } else {
            self.selected_voice_id = Some(entry.voice_id.clone());
            self.sync_selected_voice_ui(cx);
        }

        if let Some(model_id) = entry.model_id.as_ref() {
            self.select_tts_model(cx, model_id);
        }

        self.tts_speed = entry.speed;
        self.tts_pitch = entry.pitch;
        self.tts_volume = entry.volume;
        self.tts_instruct_state = TtsInstructState::from_history(entry.instruct.as_deref());
        self.tts_instruct_state.collapse();
        self.view
            .text_input(ids!(
                content_wrapper.main_content.left_column.content_area.tts_page.cards_container.input_section.settings_flyout.instruct_section.instruct_editor.instruct_input_scroller.instruct_input
            ))
            .set_text(cx, self.tts_instruct_state.text());
        self.update_tts_emotion_controls(cx);
        self.update_tts_param_controls(cx);

        self.show_toast(
            cx,
            self.tr(
                "已将历史记录填充到编辑区",
                "History entry loaded into editor",
            ),
        );
    }

    fn delete_history_entry(&mut self, cx: &mut Cx, entry_id: &str) {
        if let Some(index) = self.tts_history.iter().position(|h| h.id == entry_id) {
            let removed = self.tts_history.remove(index);
            let _ = tts_history::delete_audio_file(&removed.audio_file);
            self.persist_tts_history(cx);
            self.update_history_display(cx);
            self.show_toast(cx, self.tr("历史记录已删除", "History item deleted"));
        }
    }

    fn clear_tts_history(&mut self, cx: &mut Cx) {
        for entry in &self.tts_history {
            let _ = tts_history::delete_audio_file(&entry.audio_file);
        }
        self.tts_history.clear();
        self.persist_tts_history(cx);
        self.update_history_display(cx);
        self.show_toast(cx, self.tr("已清空历史记录", "History cleared"));
    }

    fn update_playback_progress(&mut self, cx: &mut Cx) {
        // Calculate total duration and current position
        let audio_len = self.playback_audio_total_samples();
        let effective_rate = self.playback_audio_sample_rate();
        if audio_len == 0 || effective_rate == 0 {
            return;
        }

        let total_duration = audio_len as f32 / effective_rate as f32;
        let current_time = self.audio_playing_time as f32;
        let progress = (current_time / total_duration).min(1.0).max(0.0);

        // Update current time label
        let mins = (current_time / 60.0) as u32;
        let secs = (current_time % 60.0) as u32;
        let time_str = format!("{:02}:{:02}", mins, secs);
        self.view
            .label(ids!(
                content_wrapper
                    .audio_player_bar
                    .playback_controls
                    .progress_row
                    .current_time
            ))
            .set_text(cx, &time_str);

        // Update progress bar
        self.view
            .view(ids!(
                content_wrapper
                    .audio_player_bar
                    .playback_controls
                    .progress_row
                    .progress_bar_container
                    .progress_bar
            ))
            .apply_over(
                cx,
                live! {
                    draw_bg: { progress: (progress as f64) }
                },
            );

        self.view.redraw(cx);
    }

    fn playback_duration_secs(&self) -> Option<f64> {
        let audio_len = self.playback_audio_total_samples();
        let effective_rate = self.playback_audio_sample_rate();
        if audio_len == 0 || effective_rate == 0 {
            return None;
        }
        Some(audio_len as f64 / effective_rate as f64)
    }

    fn clamped_seek_time(&self, requested_secs: f64) -> Option<f64> {
        let total_duration = self.playback_duration_secs()?;
        if total_duration <= 0.0 {
            return None;
        }
        let max_start = (total_duration - 0.05).max(0.0);
        Some(requested_secs.clamp(0.0, max_start))
    }

    fn stop_main_playback_for_preview(&mut self, cx: &mut Cx) {
        self.begin_playback_stretch_task();
        if let Some(player) = &self.audio_player {
            player.stop();
        }
        if self.tts_status == TTSStatus::Playing {
            self.tts_status = TTSStatus::Ready;
            self.update_playback_progress(cx);
        }
    }

    fn stop_preview_playback(&mut self, cx: &mut Cx) {
        if let Some(player) = &self.preview_player {
            player.stop();
        }
        self.preview_audio_source = None;
        self.preview_feed_cursor = 0;
        self.preview_feed_finished = true;
        self.segment_preview_playing = false;
        if self.preview_playing_voice_id.take().is_some() {
            let voice_selector = self.view.voice_selector(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .controls_panel
                    .settings_panel
                    .voice_section
                    .voice_selector
            ));
            voice_selector.set_preview_playing(cx, None);
            self.update_voice_picker_controls(cx);
        }
    }

    fn queue_next_preview_block(&mut self) -> Option<usize> {
        let Some(source) = self.preview_audio_source.clone() else {
            self.preview_feed_finished = true;
            return None;
        };
        let block_samples = (source.sample_rate() as usize).saturating_mul(PLAYBACK_BLOCK_SECONDS);
        let block = source.read_block(self.preview_feed_cursor, block_samples);
        if block.is_empty() {
            self.preview_feed_finished = true;
            return None;
        }
        let block_len = block.len();
        let Some(player) = &self.preview_player else {
            return None;
        };
        player.write_audio_owned(block);
        self.preview_feed_cursor = self.preview_feed_cursor.saturating_add(block_len);
        self.preview_feed_finished = self.preview_feed_cursor >= source.total_samples();
        Some(block_len)
    }

    fn fill_preview_queue(&mut self, mut queued_samples: usize) {
        let sample_rate = self
            .preview_audio_source
            .as_ref()
            .map(PlaybackAudioSource::sample_rate)
            .unwrap_or_default();
        let high_water = (PLAYBACK_HIGH_WATER_SECONDS * sample_rate as f64) as usize;
        while queued_samples < high_water && !self.preview_feed_finished {
            let Some(written) = self.queue_next_preview_block() else {
                break;
            };
            queued_samples = queued_samples.saturating_add(written);
        }
    }

    fn refill_preview_queue(&mut self) {
        if self.preview_audio_source.is_none() || self.preview_feed_finished {
            return;
        }
        let should_refill = self
            .preview_player
            .as_ref()
            .map(|player| player.queued_secs() <= PLAYBACK_LOW_WATER_SECONDS)
            .unwrap_or(false);
        if should_refill {
            let queued_samples = self
                .preview_player
                .as_ref()
                .map(TTSPlayer::queued_samples)
                .unwrap_or_default();
            self.fill_preview_queue(queued_samples);
        }
    }

    fn start_playback_from_time(&mut self, cx: &mut Cx, start_time_secs: f64) -> bool {
        let Some(source) = self.playback_audio_source.clone() else {
            return false;
        };
        let effective_rate = source.sample_rate();
        if source.is_empty() || effective_rate == 0 {
            return false;
        }

        let start_time = self.clamped_seek_time(start_time_secs).unwrap_or(0.0);
        let start_sample = ((start_time * effective_rate as f64).round() as usize)
            .min(source.total_samples().saturating_sub(1));

        self.stop_preview_playback(cx);
        if let Some(player) = &self.audio_player {
            player.stop();
            self.apply_player_audio_settings();
        }
        self.begin_playback_stretch_task();
        self.playback_feed_cursor = start_sample;
        self.playback_feed_finished = false;
        self.player_active_rate = self.player_playback_rate;
        self.playback_last_queued_sample = None;
        self.tts_status = TTSStatus::Playing;
        self.fill_playback_queue(0);
        if self.playback_feed_cursor == start_sample && self.playback_stretch_pending.is_empty() {
            self.tts_status = TTSStatus::Ready;
            return false;
        }
        self.audio_playing_time = start_time;
        self.update_playback_progress(cx);
        true
    }

    fn seek_playback_to_ratio(&mut self, cx: &mut Cx, ratio: f64) {
        if self.tts_status == TTSStatus::Generating {
            return;
        }
        let Some(total_duration) = self.playback_duration_secs() else {
            return;
        };
        let target_time = self.clamped_seek_time(total_duration * ratio).unwrap_or(0.0);

        if self.tts_status == TTSStatus::Playing {
            if self.start_playback_from_time(cx, target_time) {
                self.add_log(
                    cx,
                    &format!("[INFO] [tts] Seeked playback to {:.1}s", target_time),
                );
            }
        } else {
            self.audio_playing_time = target_time;
            self.update_playback_progress(cx);
            self.update_player_bar(cx);
        }
    }

    fn handle_playback_progress_seek_event(&mut self, cx: &mut Cx, event: &Event) {
        let progress_area = self
            .view
            .view(ids!(
                content_wrapper
                    .audio_player_bar
                    .playback_controls
                    .progress_row
                    .progress_bar_container
            ))
            .area();
        if progress_area.is_empty() {
            return;
        }

        match event.hits(cx, progress_area) {
            Hit::FingerHoverOver(_) => {
                if self.has_generated_audio && self.tts_status != TTSStatus::Generating {
                    cx.set_cursor(MouseCursor::Hand);
                }
            }
            Hit::FingerDown(fe) if fe.device.is_primary_hit() => {
                let ratio = Self::slider_ratio_from_rect(fe.abs.x, fe.rect);
                self.seek_playback_to_ratio(cx, ratio);
            }
            _ => {}
        }
    }

    fn handle_player_volume_seek_event(&mut self, cx: &mut Cx, event: &Event) {
        let slider_area = self
            .view
            .view(ids!(
                content_wrapper
                    .audio_player_bar
                    .download_section
                    .player_settings_row
                    .volume_slider_container
            ))
            .area();
        if slider_area.is_empty() {
            return;
        }

        match event.hits_with_capture_overload(cx, slider_area, true) {
            Hit::FingerHoverOver(_) => {
                cx.set_cursor(MouseCursor::Hand);
            }
            Hit::FingerDown(fe) if fe.device.is_primary_hit() => {
                let ratio = Self::slider_ratio_from_rect(fe.abs.x, fe.rect);
                self.set_player_volume_from_ratio(cx, ratio);
            }
            Hit::FingerMove(fe) => {
                let ratio = Self::slider_ratio_from_rect(fe.abs.x, fe.rect);
                self.set_player_volume_from_ratio(cx, ratio);
            }
            Hit::FingerUp(fe) if fe.is_primary_hit() => {
                let ratio = Self::slider_ratio_from_rect(fe.abs.x, fe.rect);
                self.set_player_volume_from_ratio(cx, ratio);
            }
            _ => {}
        }
    }

    fn handle_preview_request(&mut self, cx: &mut Cx, voice_id: &str) {
        use crate::voice_data::VoiceSource;
        use crate::voice_persistence;

        // Get the voice selector to check preview audio path
        let voice_selector = self.view.voice_selector(ids!(
            content_wrapper
                .main_content
                .left_column
                .content_area
                .tts_page
                .cards_container
                .controls_panel
                .settings_panel
                .voice_section
                .voice_selector
        ));

        // Check if we're stopping a preview
        if self.preview_playing_voice_id.as_ref() == Some(&voice_id.to_string()) {
            // Stop preview
            if let Some(player) = &self.preview_player {
                player.stop();
            }
            self.preview_playing_voice_id = None;
            voice_selector.set_preview_playing(cx, None);
            self.add_log(cx, &format!("[INFO] [tts] Stopped preview: {}", voice_id));
            return;
        }

        // Stop any currently playing preview
        if let Some(player) = &self.preview_player {
            player.stop();
        }

        // Get voice info
        let voice = match voice_selector.get_voice(voice_id) {
            Some(v) => v,
            None => {
                self.add_log(cx, &format!("[ERROR] [tts] Voice not found: {}", voice_id));
                return;
            }
        };

        // Build the audio path based on voice source
        let audio_path = if voice.source == VoiceSource::Custom {
            // Custom voice: use reference_audio_path from persistence
            match voice_persistence::get_reference_audio_path(&voice) {
                Some(path) => path,
                None => {
                    self.add_log(
                        cx,
                        &format!(
                            "[ERROR] [tts] Custom voice has no reference audio: {}",
                            voice_id
                        ),
                    );
                    return;
                }
            }
        } else if voice.source == VoiceSource::BundledClone {
            // Bundled clone voice: use bundled reference audio as its preview.
            let ref_filename = voice.reference_audio_path.as_deref().unwrap_or("ref.wav");
            match self.resolve_bundled_clone_ref_path(&voice.id, ref_filename) {
                Some(path) => path,
                None => {
                    self.add_log(
                        cx,
                        &format!("[WARN] [tts] Bundled ref audio not found for: {}", voice_id),
                    );
                    return;
                }
            }
        } else {
            // Built-in voice: resolve preview audio path by backend
            let preview_file = match &voice.preview_audio {
                Some(f) => f.clone(),
                None => {
                    self.add_log(
                        cx,
                        &format!("[WARN] [tts] No preview audio for: {}", voice_id),
                    );
                    return;
                }
            };

            if self.app_preferences.inference_backend == "qwen3_tts_mlx" {
                // Qwen3 preview audio: bundled in repo/app
                self.resolve_qwen_preview_path(&preview_file)
            } else {
                // PrimeSpeech preview audio: reference WAVs in the models dir
                let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
                home.join(".dora")
                    .join("models")
                    .join("primespeech")
                    .join("moyoyo")
                    .join("ref_audios")
                    .join(&preview_file)
            }
        };

        if !audio_path.exists() {
            self.add_log(
                cx,
                &format!("[ERROR] [tts] Preview audio not found: {:?}", audio_path),
            );
            return;
        }

        // Load WAV file
        match self.load_wav_file(&audio_path) {
            Ok(samples) => {
                self.preview_audio_source = None;
                self.preview_feed_finished = true;
                // Initialize preview player if needed
                if self.preview_player.is_none() {
                    self.preview_player = Some(TTSPlayer::new_with_output_device(
                        24000,
                        self.app_preferences.preferred_output_device.as_deref(),
                    ));
                }

                // Play the audio
                if let Some(player) = &self.preview_player {
                    player.write_audio(&samples);
                    player.resume();
                }

                self.preview_playing_voice_id = Some(voice_id.to_string());
                voice_selector.set_preview_playing(cx, Some(voice_id.to_string()));
                self.add_log(
                    cx,
                    &format!(
                        "[INFO] [tts] Playing preview: {} ({:.1}s)",
                        voice_id,
                        samples.len() as f32 / 32000.0
                    ),
                );
            }
            Err(e) => {
                self.add_log(cx, &format!("[ERROR] [tts] Failed to load preview: {}", e));
            }
        }
    }

    /// Resolve the path for a Qwen3-TTS built-in voice preview WAV file.
    /// Search order:
    ///   1. App bundle: $MOXIN_APP_RESOURCES/qwen3-previews/<file>
    ///   2. Dev repo:   <exe>/../../node-hub/dora-qwen3-tts-mlx/previews/<file>
    ///   3. Fallback:   ~/.OminiX/models/qwen3-tts-mlx/previews/<file>
    fn resolve_qwen_preview_path(&self, filename: &str) -> PathBuf {
        // 1. Bundle location (set by the launcher script for packaged apps)
        if let Ok(res) = std::env::var("MOXIN_APP_RESOURCES") {
            let p = PathBuf::from(&res).join("qwen3-previews").join(filename);
            if p.exists() {
                return p;
            }
        }
        // 2. Dev: repo root relative to the compiled binary
        //    target/{debug,release}/moxin-voice-shell → ../../node-hub/dora-qwen3-tts-mlx/previews
        if let Ok(exe) = std::env::current_exe() {
            if let Some(target_dir) = exe.parent().and_then(|d| d.parent()) {
                let p = target_dir
                    .join("node-hub")
                    .join("dora-qwen3-tts-mlx")
                    .join("previews")
                    .join(filename);
                if p.exists() {
                    return p;
                }
            }
        }
        // 3. Fallback: user-local generated previews
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
        home.join(".OminiX")
            .join("models")
            .join("qwen3-tts-mlx")
            .join("previews")
            .join(filename)
    }

    /// Resolve the absolute path of a bundled clone voice's reference audio.
    /// voice_id: e.g. "baiyang", filename: e.g. "ref.wav"
    fn resolve_bundled_clone_ref_path(&self, voice_id: &str, filename: &str) -> Option<PathBuf> {
        // 1. App bundle
        if let Ok(res) = std::env::var("MOXIN_APP_RESOURCES") {
            let p = PathBuf::from(&res)
                .join("qwen3-voices")
                .join(voice_id)
                .join(filename);
            if p.exists() {
                return Some(p);
            }
        }
        // 2. Dev: current working directory (project root when using cargo run)
        if let Ok(cwd) = std::env::current_dir() {
            let p = cwd
                .join("node-hub")
                .join("dora-qwen3-tts-mlx")
                .join("voices")
                .join(voice_id)
                .join(filename);
            if p.exists() {
                return Some(p);
            }
        }
        // 3. Dev: exe path → target/{debug,release}/../../../ (project root)
        if let Ok(exe) = std::env::current_exe() {
            if let Some(project_dir) = exe
                .parent()
                .and_then(|d| d.parent())
                .and_then(|d| d.parent())
            {
                let p = project_dir
                    .join("node-hub")
                    .join("dora-qwen3-tts-mlx")
                    .join("voices")
                    .join(voice_id)
                    .join(filename);
                if p.exists() {
                    return Some(p);
                }
            }
        }
        None
    }

    fn load_wav_mono_file(&self, path: &PathBuf) -> Result<(Vec<f32>, u32), String> {
        let reader = WavReader::open(path).map_err(|e| format!("Failed to open WAV: {}", e))?;
        let spec = reader.spec();
        let sample_rate = spec.sample_rate;
        let channels = spec.channels as usize;

        // Read samples based on format
        let samples: Vec<f32> = match spec.sample_format {
            hound::SampleFormat::Int => {
                let bits = spec.bits_per_sample;
                let max_val = (1 << (bits - 1)) as f32;
                reader
                    .into_samples::<i32>()
                    .filter_map(Result::ok)
                    .map(|s| s as f32 / max_val)
                    .collect()
            }
            hound::SampleFormat::Float => reader
                .into_samples::<f32>()
                .filter_map(Result::ok)
                .collect(),
        };

        // Convert to mono if stereo
        let mono_samples: Vec<f32> = if channels > 1 {
            samples
                .chunks(channels)
                .map(|chunk| chunk.iter().sum::<f32>() / channels as f32)
                .collect()
        } else {
            samples
        };

        Ok((mono_samples, sample_rate))
    }

    fn load_wav_file(&self, path: &PathBuf) -> Result<Vec<f32>, String> {
        let (samples, sample_rate) = self.load_wav_mono_file(path)?;
        let source = PlaybackAudioSource::from_contiguous(Arc::new(samples), sample_rate, 24_000);
        Ok(source.read_block(0, source.total_samples()))
    }

    fn show_toast(&mut self, cx: &mut Cx, message: &str) {
        self.toast_message = message.to_string();
        self.toast_visible = true;

        // Update toast label
        self.view
            .label(ids!(toast_overlay.download_toast.toast_content.toast_label))
            .set_text(cx, message);

        // Show toast
        self.view
            .view(ids!(toast_overlay.download_toast))
            .set_visible(cx, true);

        // Start timer to auto-hide after 3 seconds
        self.toast_timer = cx.start_timeout(3.0);

        self.view.redraw(cx);
    }

    fn show_or_queue_update_toast(&mut self, cx: &mut Cx, message: String) {
        if self.loading_dismissed {
            self.show_toast(cx, &message);
        } else {
            self.pending_app_update_toast = Some(message);
        }
    }

    fn hide_toast(&mut self, cx: &mut Cx) {
        self.toast_visible = false;
        self.view
            .view(ids!(toast_overlay.download_toast))
            .set_visible(cx, false);
        self.view.redraw(cx);
    }

    fn maybe_start_background_update_check(&mut self) {
        if self.app_update_check_started {
            return;
        }

        let Some(started_at) = self.app_update_check_started_at else {
            self.app_update_check_started_at = Some(std::time::Instant::now());
            return;
        };

        if started_at.elapsed() < Duration::from_secs(8) {
            return;
        }

        if matches!(self.runtime_init_state, RuntimeInitState::Running) {
            return;
        }

        let current_version = self.current_display_version();
        let (tx, rx) = mpsc::channel::<AppUpdateEvent>();
        self.app_update_rx = Some(rx);
        self.app_update_check_started = true;

        thread::spawn(move || {
            let _ = tx.send(AppUpdateEvent::Checking);
            match app_update::check_and_prepare_update(&current_version) {
                Ok(app_update::CheckOutcome::NoUpdate) => {
                    let _ = tx.send(AppUpdateEvent::NoUpdate);
                }
                Ok(app_update::CheckOutcome::Ready {
                    update,
                    fresh_download,
                }) => {
                    let _ = tx.send(AppUpdateEvent::Ready {
                        update,
                        fresh_download,
                    });
                }
                Err(err) => {
                    let _ = tx.send(AppUpdateEvent::Failed(err));
                }
            }
        });
    }

    fn poll_app_update(&mut self, cx: &mut Cx) {
        let mut latest_event: Option<AppUpdateEvent> = None;
        if let Some(rx) = &self.app_update_rx {
            while let Ok(ev) = rx.try_recv() {
                latest_event = Some(ev);
            }
        }

        let Some(event) = latest_event else {
            return;
        };

        match event {
            AppUpdateEvent::Checking => {
                self.app_update_state = AppUpdateState::Checking;
                self.add_log(cx, "[INFO] [update] Checking for app updates...");
            }
            AppUpdateEvent::Ready {
                update,
                fresh_download,
            } => {
                let version = update.version.clone();
                self.app_update_state = AppUpdateState::Ready(update);
                self.app_update_rx = None;
                self.add_log(
                    cx,
                    &format!("[INFO] [update] Update {} is ready to install", version),
                );
                if fresh_download {
                    let message = if self.is_english() {
                        format!(
                            "New version {} is ready. Open Settings to install.",
                            version
                        )
                    } else {
                        format!("新版本 {} 已下载完成，请前往设置安装。", version)
                    };
                    self.show_or_queue_update_toast(cx, message);
                }
            }
            AppUpdateEvent::NoUpdate => {
                self.app_update_state = AppUpdateState::Idle;
                self.app_update_rx = None;
            }
            AppUpdateEvent::Failed(err) => {
                self.app_update_state = AppUpdateState::Failed;
                self.app_update_rx = None;
                self.add_log(cx, &format!("[WARN] [update] {}", err));
            }
        }

        self.refresh_update_affordances(cx);
        self.update_user_settings_tabs(cx);
    }

    fn install_ready_update(&mut self, cx: &mut Cx) {
        let Some(update) = self.ready_update().cloned() else {
            self.show_toast(
                cx,
                self.tr("暂无可安装的新版本", "No downloaded update is ready yet"),
            );
            return;
        };

        if let Err(err) = app_update::launch_update_installer(&update) {
            self.show_toast(
                cx,
                self.tr(
                    "启动安装失败，请稍后重试",
                    "Failed to start update installer",
                ),
            );
            self.add_log(cx, &format!("[ERROR] [update] {}", err));
            return;
        }

        self.perform_shutdown_cleanup_for_update();
        std::process::exit(0);
    }

    fn perform_shutdown_cleanup_for_update(&mut self) {
        if let Some(player) = &self.audio_player {
            player.stop();
        }
        if let Some(player) = &self.preview_player {
            player.stop();
        }

        drop(self.translation_dora.take());
        drop(self.dora.take());

        Self::ensure_bundle_bin_on_path();
        let startup_lock_path = Self::dora_startup_lock_path();
        match DoraStartupLockGuard::acquire(startup_lock_path, Duration::from_secs(5)) {
            Ok(_lock) => match Command::new("dora").arg("destroy").status() {
                Ok(status) if status.success() => {
                    ::log::info!("Dora runtime destroyed for update install");
                }
                Ok(status) => {
                    ::log::warn!(
                        "`dora destroy` exited with status {} during update install",
                        status
                    );
                }
                Err(err) => {
                    ::log::warn!("Failed to run `dora destroy` for update install: {}", err);
                }
            },
            Err(err) => {
                ::log::warn!(
                    "Failed to acquire Dora startup lock during update install: {}",
                    err
                );
            }
        }
    }

    fn update_log_display(&mut self, cx: &mut Cx) {
        let log_text = if self.log_entries.is_empty() {
            self.tr("*暂无日志*", "*No log entries*").to_string()
        } else {
            self.log_entries
                .iter()
                .map(|s| s.as_str())
                .collect::<Vec<_>>()
                .join("\n\n")
        };

        self.view
            .markdown(ids!(
                main_content
                    .log_section
                    .log_content_column
                    .log_scroll
                    .log_content_wrapper
                    .log_content
            ))
            .set_text(cx, &log_text);
        self.view.redraw(cx);
    }

    fn toggle_log_panel(&mut self, cx: &mut Cx) {
        self.log_panel_collapsed = !self.log_panel_collapsed;

        if self.log_panel_width == 0.0 {
            self.log_panel_width = 320.0;
        }

        if self.log_panel_collapsed {
            self.view
                .view(ids!(content_wrapper.main_content.log_section))
                .apply_over(cx, live! { width: Fit });
            self.view
                .view(ids!(
                    content_wrapper.main_content.log_section.log_content_column
                ))
                .set_visible(cx, false);
            self.view
                .button(ids!(
                    content_wrapper
                        .main_content
                        .log_section
                        .toggle_column
                        .toggle_log_btn
                ))
                .set_text(cx, "<");
            self.view
                .view(ids!(content_wrapper.main_content.splitter))
                .apply_over(cx, live! { width: 0 });
        } else {
            let width = self.log_panel_width;
            self.view
                .view(ids!(content_wrapper.main_content.log_section))
                .apply_over(cx, live! { width: (width) });
            self.view
                .view(ids!(
                    content_wrapper.main_content.log_section.log_content_column
                ))
                .set_visible(cx, true);
            self.view
                .button(ids!(
                    content_wrapper
                        .main_content
                        .log_section
                        .toggle_column
                        .toggle_log_btn
                ))
                .set_text(cx, ">");
            self.view
                .view(ids!(content_wrapper.main_content.splitter))
                .apply_over(cx, live! { width: 16 });
        }

        self.view.redraw(cx);
    }

    fn resize_log_panel(&mut self, cx: &mut Cx, abs_x: f64) {
        let container_rect = self.view.area().rect(cx);
        let padding = 16.0;
        let new_log_width = (container_rect.pos.x + container_rect.size.x - abs_x - padding)
            .max(150.0)
            .min(container_rect.size.x - 400.0);

        self.log_panel_width = new_log_width;

        self.view
            .view(ids!(content_wrapper.main_content.log_section))
            .apply_over(cx, live! { width: (new_log_width) });

        self.view.redraw(cx);
    }

    fn start_qwen_model_download(
        &mut self,
        cx: &mut Cx,
        target_backend: &str,
        need_custom: bool,
        need_base: bool,
    ) {
        if self.qwen_download_in_progress {
            self.show_toast(
                cx,
                self.tr(
                    "Qwen 模型下载中，请稍候",
                    "Qwen model download already running",
                ),
            );
            return;
        }
        if !need_custom && !need_base {
            return;
        }

        let Some(script_path) = Self::resolve_qwen_download_script_path() else {
            self.show_toast(
                cx,
                self.tr(
                    "未找到 Qwen 下载脚本，无法启动下载",
                    "Qwen download script not found",
                ),
            );
            return;
        };

        let qwen_root = Self::qwen_root_dir();
        let log_dir = PathBuf::from(
            std::env::var("HOME").unwrap_or_else(|_| ".".to_string()) + "/Library/Logs/MoxinVoice",
        );
        let _ = std::fs::create_dir_all(&log_dir);
        let qwen_log = log_dir.join("qwen_model_download.log");

        self.qwen_download_in_progress = true;
        self.qwen_model_status_text = self.tr("下载中...", "Downloading...").to_string();
        self.update_user_settings_page(cx);
        self.add_log(
            cx,
            &format!(
                "[INFO] [qwen] Starting background model download (backend={}, custom={}, base={})",
                target_backend, need_custom, need_base
            ),
        );

        let (tx, rx) = mpsc::channel::<QwenModelDownloadEvent>();
        self.qwen_download_rx = Some(rx);

        thread::spawn(move || {
            let _ = tx.send(QwenModelDownloadEvent::Stage(
                "Preparing Qwen model download".to_string(),
            ));

            let conda_bin = std::env::var("MOXIN_CONDA_BIN")
                .ok()
                .filter(|p| Path::new(p).exists())
                .unwrap_or_else(|| {
                    let home = std::env::var("HOME").unwrap_or_else(|_| ".".to_string());
                    format!("{}/.moxinvoice/conda/bin/conda", home)
                });
            let conda_env_prefix =
                std::env::var("MOXIN_CONDA_ENV_PREFIX")
                    .ok()
                    .unwrap_or_else(|| {
                        let home = std::env::var("HOME").unwrap_or_else(|_| ".".to_string());
                        let env = std::env::var("MOXIN_CONDA_ENV")
                            .unwrap_or_else(|_| "moxin-studio".to_string());
                        format!("{}/.moxinvoice/conda/envs/{}", home, env)
                    });

            let log_file = match OpenOptions::new()
                .create(true)
                .truncate(true)
                .write(true)
                .open(&qwen_log)
            {
                Ok(f) => f,
                Err(err) => {
                    let _ = tx.send(QwenModelDownloadEvent::DoneErr(format!(
                        "open qwen download log failed: {}",
                        err
                    )));
                    return;
                }
            };
            let log_file_err = match log_file.try_clone() {
                Ok(f) => f,
                Err(err) => {
                    let _ = tx.send(QwenModelDownloadEvent::DoneErr(format!(
                        "clone qwen download log fd failed: {}",
                        err
                    )));
                    return;
                }
            };

            let mut cmd = if Path::new(&conda_bin).exists() && Path::new(&conda_env_prefix).exists()
            {
                let mut c = Command::new(&conda_bin);
                c.arg("run")
                    .arg("-p")
                    .arg(&conda_env_prefix)
                    .arg("python")
                    .arg(&script_path);
                c
            } else {
                let mut c = Command::new("python3");
                c.arg(&script_path);
                c
            };

            cmd.arg("--root").arg(&qwen_root);
            if need_custom {
                cmd.arg("--need-custom");
            }
            if need_base {
                cmd.arg("--need-base");
            }
            cmd.stdout(Stdio::from(log_file));
            cmd.stderr(Stdio::from(log_file_err));

            let status = cmd.status();
            match status {
                Ok(s) if s.success() => {
                    let _ = tx.send(QwenModelDownloadEvent::DoneOk);
                }
                Ok(s) => {
                    let _ = tx.send(QwenModelDownloadEvent::DoneErr(format!(
                        "qwen model download exited with status {} (log: {})",
                        s,
                        qwen_log.display()
                    )));
                }
                Err(err) => {
                    let _ = tx.send(QwenModelDownloadEvent::DoneErr(format!(
                        "failed to launch qwen model download: {}",
                        err
                    )));
                }
            }
        });
    }

    fn poll_qwen_model_download(&mut self, cx: &mut Cx) {
        let mut latest_event: Option<QwenModelDownloadEvent> = None;
        if let Some(rx) = &self.qwen_download_rx {
            while let Ok(ev) = rx.try_recv() {
                latest_event = Some(ev);
            }
        }
        let Some(event) = latest_event else {
            return;
        };

        match event {
            QwenModelDownloadEvent::Stage(detail) => {
                self.qwen_model_status_text = self.tr("下载中...", "Downloading...").to_string();
                self.add_log(cx, &format!("[INFO] [qwen] {}", detail));
                self.update_user_settings_page(cx);
            }
            QwenModelDownloadEvent::DoneOk => {
                self.qwen_download_in_progress = false;
                self.qwen_download_rx = None;
                let custom_ready = Self::qwen_custom_ready();
                let base_ready = Self::qwen_base_ready();
                self.qwen_model_status_text = if custom_ready && base_ready {
                    self.tr("已就绪（推理+克隆）", "Ready (inference + clone)")
                        .to_string()
                } else if custom_ready {
                    self.tr("部分就绪（仅推理）", "Partially ready (inference only)")
                        .to_string()
                } else {
                    self.tr("未就绪", "Not ready").to_string()
                };
                self.update_user_settings_page(cx);
                self.show_toast(
                    cx,
                    self.tr(
                        "Qwen 模型下载完成，请在设置中重新切换后端",
                        "Qwen models downloaded. Please switch backend again in Settings",
                    ),
                );
                self.add_log(cx, "[INFO] [qwen] Qwen model download completed");
            }
            QwenModelDownloadEvent::DoneErr(err) => {
                self.qwen_download_in_progress = false;
                self.qwen_download_rx = None;
                self.qwen_model_status_text = self.tr("下载失败", "Download failed").to_string();
                self.update_user_settings_page(cx);
                self.show_toast(
                    cx,
                    self.tr(
                        "Qwen 模型下载失败，请查看日志",
                        "Qwen model download failed. Check logs",
                    ),
                );
                self.add_log(cx, &format!("[ERROR] [qwen] {}", err));
            }
        }
    }

    fn start_runtime_initialization(&mut self, cx: &mut Cx) {
        Self::ensure_bundle_bin_on_path();

        let app_resources = match std::env::var("MOXIN_APP_RESOURCES") {
            Ok(v) => PathBuf::from(v),
            Err(_) => {
                // Dev mode default: skip bootstrap/preflight unless explicitly enabled.
                let enable_dev_bootstrap =
                    std::env::var("MOXIN_ENABLE_DEV_BOOTSTRAP").ok().as_deref() == Some("1");
                let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
                let direct = cwd.join("scripts").join("macos_preflight.sh");
                if enable_dev_bootstrap && direct.exists() {
                    cwd
                } else {
                    self.runtime_init_state = RuntimeInitState::Ready;
                    self.runtime_init_status_text =
                        self.tr("连接中...", "Connecting...").to_string();
                    self.runtime_init_detail_text = self
                        .tr("正在启动 TTS 数据流引擎", "Starting TTS dataflow engine")
                        .to_string();
                    self.runtime_init_progress = 0.0;
                    self.runtime_init_download_ui_active = false;
                    return;
                }
            }
        };

        let pre = app_resources.join("scripts/macos_preflight.sh");
        let boot = app_resources.join("scripts/macos_bootstrap.sh");
        if !pre.exists() || !boot.exists() {
            self.runtime_init_state = RuntimeInitState::Ready;
            self.runtime_init_status_text = self.tr("连接中...", "Connecting...").to_string();
            self.runtime_init_detail_text = self
                .tr("正在启动 TTS 数据流引擎", "Starting TTS dataflow engine")
                .to_string();
            self.runtime_init_progress = 0.0;
            self.runtime_init_download_ui_active = false;
            return;
        }

        let log_dir = PathBuf::from(
            std::env::var("HOME").unwrap_or_else(|_| ".".to_string()) + "/Library/Logs/MoxinVoice",
        );
        let _ = std::fs::create_dir_all(&log_dir);
        let bootstrap_log = log_dir.join("bootstrap.log");
        let bootstrap_state = log_dir.join("bootstrap_state.txt");
        let bootstrap_lock = log_dir.join(BOOTSTRAP_LOCK_FILE);
        let attach_existing_bootstrap = bootstrap_lock_is_active(&bootstrap_lock);
        if !attach_existing_bootstrap {
            let _ = std::fs::remove_file(&bootstrap_state);
        }

        self.runtime_init_state = RuntimeInitState::Running;
        self.runtime_init_status_text = self.tr("初始化中...", "Initializing...").to_string();
        self.runtime_init_detail_text = self
            .tr("正在检查运行环境", "Checking runtime environment")
            .to_string();
        self.runtime_init_progress = 0.0;
        self.runtime_init_download_ui_active = false;

        if attach_existing_bootstrap {
            self.add_log(
                cx,
                "[INFO] [startup] Resuming existing runtime initialization...",
            );
        } else {
            self.add_log(cx, "[INFO] [startup] Checking runtime dependencies...");
        }

        let (tx, rx) = mpsc::channel::<RuntimeInitEvent>();
        self.runtime_init_rx = Some(rx);
        let inference_backend = self.app_preferences.inference_backend.clone();
        let zero_shot_backend = self.app_preferences.zero_shot_backend.clone();
        let app_resources_env = app_resources.clone();
        let bootstrap_lock_for_thread = bootstrap_lock.clone();

        thread::spawn(move || {
            let _ = tx.send(RuntimeInitEvent::Stage {
                status: "Initializing runtime".to_string(),
                detail: "Checking environment".to_string(),
                progress: 0.0,
            });

            let pre_ok = Command::new(&pre)
                .env("MOXIN_APP_RESOURCES", &app_resources_env)
                .env("MOXIN_INFERENCE_BACKEND", &inference_backend)
                .env("MOXIN_ZERO_SHOT_BACKEND", &zero_shot_backend)
                .arg("--quick")
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            if pre_ok {
                let _ = tx.send(RuntimeInitEvent::DoneOk);
                return;
            }

            if attach_existing_bootstrap {
                let _ = tx.send(RuntimeInitEvent::Stage {
                    status: "Initializing runtime".to_string(),
                    detail: "Resuming existing model download".to_string(),
                    progress: 0.0,
                });

                let mut last_state = String::new();
                loop {
                    send_bootstrap_state_update(&bootstrap_state, &mut last_state, &tx);
                    if !bootstrap_lock_is_active(&bootstrap_lock_for_thread) {
                        break;
                    }
                    std::thread::sleep(std::time::Duration::from_millis(300));
                }
                send_bootstrap_state_update(&bootstrap_state, &mut last_state, &tx);

                let pre_ok = Command::new(&pre)
                    .env("MOXIN_APP_RESOURCES", &app_resources_env)
                    .env("MOXIN_INFERENCE_BACKEND", &inference_backend)
                    .env("MOXIN_ZERO_SHOT_BACKEND", &zero_shot_backend)
                    .arg("--quick")
                    .status()
                    .map(|s| s.success())
                    .unwrap_or(false);
                if pre_ok {
                    let _ = tx.send(RuntimeInitEvent::DoneOk);
                } else {
                    let _ = tx.send(RuntimeInitEvent::DoneErr(format!(
                        "Initialization failed. Check: {}",
                        bootstrap_log.display()
                    )));
                }
                return;
            }

            let _ = tx.send(RuntimeInitEvent::Stage {
                status: "Initializing runtime (0/10)".to_string(),
                detail:
                    "Installing dependencies and models (first launch may take several minutes)"
                        .to_string(),
                progress: 0.0,
            });

            let log_file = match OpenOptions::new()
                .create(true)
                .truncate(true)
                .write(true)
                .open(&bootstrap_log)
            {
                Ok(f) => f,
                Err(err) => {
                    let _ = tx.send(RuntimeInitEvent::DoneErr(format!(
                        "Cannot open bootstrap log: {}",
                        err
                    )));
                    return;
                }
            };
            let log_file_err = match log_file.try_clone() {
                Ok(f) => f,
                Err(err) => {
                    let _ = tx.send(RuntimeInitEvent::DoneErr(format!(
                        "Cannot clone bootstrap log fd: {}",
                        err
                    )));
                    return;
                }
            };

            let mut child = match Command::new(&boot)
                .env("MOXIN_APP_RESOURCES", &app_resources_env)
                .env("MOXIN_INFERENCE_BACKEND", &inference_backend)
                .env("MOXIN_ZERO_SHOT_BACKEND", &zero_shot_backend)
                .env("MOXIN_BOOTSTRAP_STATE_PATH", &bootstrap_state)
                .stdout(Stdio::from(log_file))
                .stderr(Stdio::from(log_file_err))
                .spawn()
            {
                Ok(c) => c,
                Err(err) => {
                    let _ = tx.send(RuntimeInitEvent::DoneErr(format!(
                        "Failed to launch bootstrap: {}",
                        err
                    )));
                    return;
                }
            };

            let mut last_state = String::new();
            let boot_ok = loop {
                send_bootstrap_state_update(&bootstrap_state, &mut last_state, &tx);

                match child.try_wait() {
                    Ok(Some(status)) => break status.success(),
                    Ok(None) => {
                        std::thread::sleep(std::time::Duration::from_millis(300));
                    }
                    Err(_) => break false,
                }
            };

            if !boot_ok {
                let _ = tx.send(RuntimeInitEvent::DoneErr(format!(
                    "Initialization failed. Check: {}",
                    bootstrap_log.display()
                )));
                return;
            }

            let _ = tx.send(RuntimeInitEvent::Stage {
                status: "Runtime ready".to_string(),
                detail: "Preparing TTS engine".to_string(),
                progress: 1.0,
            });
            let _ = tx.send(RuntimeInitEvent::DoneOk);
        });
    }

    fn poll_runtime_initialization(&mut self, cx: &mut Cx) {
        let mut terminal_event: Option<RuntimeInitEvent> = None;
        if let Some(rx) = &self.runtime_init_rx {
            while let Ok(ev) = rx.try_recv() {
                match ev {
                    RuntimeInitEvent::Stage {
                        status,
                        detail,
                        progress,
                    } => {
                        // Apply every Stage immediately so progress is never dropped.
                        self.runtime_init_status_text = status;
                        self.runtime_init_detail_text = detail;
                        self.runtime_init_progress =
                            runtime_init_next_display_progress(self.runtime_init_progress, progress);
                        self.runtime_init_download_ui_active = true;
                    }
                    done => {
                        terminal_event = Some(done);
                    }
                }
            }
        }

        if let Some(ev) = terminal_event {
            match ev {
                RuntimeInitEvent::DoneOk => {
                    self.runtime_init_state = RuntimeInitState::Ready;
                    self.runtime_init_status_text =
                        self.tr("连接中...", "Connecting...").to_string();
                    self.runtime_init_detail_text = self
                        .tr("正在启动 TTS 数据流引擎", "Starting TTS dataflow engine")
                        .to_string();
                    self.runtime_init_progress = 0.0;
                    self.runtime_init_download_ui_active = false;
                    self.runtime_init_rx = None;
                    self.add_log(cx, "[INFO] [startup] Runtime initialization completed");
                }
                RuntimeInitEvent::DoneErr(message) => {
                    self.runtime_init_state = RuntimeInitState::Failed;
                    self.runtime_init_status_text =
                        self.tr("初始化失败", "Initialization failed").to_string();
                    self.runtime_init_detail_text = message.clone();
                    self.runtime_init_download_ui_active = true;
                    self.runtime_init_rx = None;
                    self.add_log(cx, &format!("[ERROR] [startup] {}", message));
                }
                RuntimeInitEvent::Stage { .. } => unreachable!(),
            }
        }
    }

    fn runtime_init_progress_for_display(&self) -> f64 {
        runtime_init_progress_for_display_value(
            self.runtime_init_progress,
            &self.runtime_init_status_text,
        )
    }

    fn update_loading_overlay_runtime_status(&mut self, cx: &mut Cx) {
        let pct = self.runtime_init_progress_for_display();
        let show_download_ui = should_show_runtime_download_ui(
            self.runtime_init_state,
            self.runtime_init_download_ui_active,
        );
        let center_detail = if show_download_ui {
            String::new()
        } else {
            self.runtime_init_detail_text.clone()
        };
        let progress_status = if show_download_ui {
            self.runtime_init_detail_text.clone()
        } else {
            String::new()
        };
        self.view.apply_over(
            cx,
            live! {
                loading_overlay = {
                    loading_center = {
                        loading_content = {
                            loading_status = { text: (self.runtime_init_status_text.clone()) }
                            loading_detail = { text: (center_detail) }
                        }
                    }
                    loading_progress_container = {
                        visible: (show_download_ui)
                        loading_progress_status_row = {
                            loading_progress_status = { text: (progress_status) }
                        }
                        loading_progress_bar = {
                            draw_bg: { progress: (pct) }
                        }
                    }
                }
            },
        );
    }

    fn auto_start_dataflow(&mut self, cx: &mut Cx) {
        Self::ensure_bundle_bin_on_path();

        let should_start = self.dora.as_ref().map(|d| !d.is_running()).unwrap_or(false);
        if !should_start || self.dora_start_in_flight {
            return;
        }

        let dataflow_path = match self.materialize_runtime_dataflow(cx) {
            Ok(path) => path,
            Err(err) => {
                self.add_log(
                    cx,
                    &format!("[ERROR] [tts] Failed to prepare runtime dataflow: {}", err),
                );
                self.dora_start_in_flight = false;
                return;
            }
        };
        if !dataflow_path.exists() {
            self.add_log(
                cx,
                &format!(
                    "[ERROR] [tts] Dataflow file not found: {}",
                    dataflow_path.display()
                ),
            );
            self.dora_start_in_flight = false;
            return;
        }
        self.dora_start_in_flight = true;
        self.dora_start_attempt_at = Some(std::time::Instant::now());
        self.dora_pending_dataflow_path = Some(dataflow_path);

        self.add_log(cx, "[INFO] [tts] Ensuring Dora runtime is up...");
        let (tx, rx) = mpsc::channel::<DoraStartupEvent>();
        self.dora_start_rx = Some(rx);
        let startup_lock_path = Self::dora_startup_lock_path();

        thread::spawn(move || {
            let _ = tx.send(DoraStartupEvent::Stage(
                "Waiting for Dora startup lock".to_string(),
            ));

            let _startup_lock =
                match DoraStartupLockGuard::acquire(startup_lock_path, Duration::from_secs(15)) {
                    Ok(lock) => lock,
                    Err(err) => {
                        let _ = tx.send(DoraStartupEvent::Failed(err));
                        return;
                    }
                };

            let _ = tx.send(DoraStartupEvent::Stage(
                "Resetting Dora runtime".to_string(),
            ));

            match Command::new("dora").arg("destroy").status() {
                Ok(_) => {}
                Err(err) => {
                    let _ = tx.send(DoraStartupEvent::Failed(format!(
                        "Failed to run `dora destroy`: {}",
                        err
                    )));
                    return;
                }
            }

            thread::sleep(Duration::from_millis(500));

            let _ = tx.send(DoraStartupEvent::Stage("Starting Dora runtime".to_string()));

            match Command::new("dora").args(["up"]).status() {
                Ok(status) if status.success() => {}
                Ok(status) => {
                    let _ = tx.send(DoraStartupEvent::Failed(format!(
                        "`dora up` exited with status {}",
                        status
                    )));
                    return;
                }
                Err(err) => {
                    let _ = tx.send(DoraStartupEvent::Failed(format!(
                        "Failed to run `dora up`: {}",
                        err
                    )));
                    return;
                }
            }

            let _ = tx.send(DoraStartupEvent::Stage(
                "Waiting for Dora runtime readiness".to_string(),
            ));

            let mut dora_ready = false;
            for _ in 0..20 {
                dora_ready = Command::new("dora")
                    .args(["system", "status"])
                    .status()
                    .map(|status| status.success())
                    .unwrap_or(false);
                if dora_ready {
                    break;
                }
                thread::sleep(Duration::from_millis(250));
            }

            if dora_ready {
                let _ = tx.send(DoraStartupEvent::Ready);
            } else {
                let _ = tx.send(DoraStartupEvent::Failed(
                    "Dora runtime not ready after startup".to_string(),
                ));
            }
        });
    }

    fn poll_dora_startup(&mut self, cx: &mut Cx) {
        let mut latest_event: Option<DoraStartupEvent> = None;
        if let Some(rx) = &self.dora_start_rx {
            while let Ok(event) = rx.try_recv() {
                latest_event = Some(event);
            }
        }

        let Some(event) = latest_event else {
            return;
        };

        match event {
            DoraStartupEvent::Stage(detail) => {
                self.add_log(cx, &format!("[INFO] [tts] {}", detail));
            }
            DoraStartupEvent::Ready => {
                self.dora_start_rx = None;
                self.add_log(cx, "[INFO] [tts] Dora runtime ready");

                let Some(dataflow_path) = self.dora_pending_dataflow_path.take() else {
                    self.dora_start_in_flight = false;
                    self.dora_started = false;
                    self.add_log(cx, "[ERROR] [tts] Missing pending dataflow path");
                    return;
                };

                self.add_log(cx, "[INFO] [tts] Auto-starting TTS dataflow...");
                if let Some(dora) = &mut self.dora {
                    if dora.start_dataflow(dataflow_path) {
                        self.add_log(
                            cx,
                            "[INFO] [tts] Dataflow start command submitted, connecting...",
                        );
                    } else {
                        self.dora_start_in_flight = false;
                        self.dora_started = false;
                        self.add_log(cx, "[ERROR] [tts] Failed to submit Dora start command");
                    }
                } else {
                    self.dora_start_in_flight = false;
                    self.dora_started = false;
                    self.add_log(cx, "[ERROR] [tts] Dora integration not initialized");
                }
            }
            DoraStartupEvent::Failed(message) => {
                self.dora_start_rx = None;
                self.dora_pending_dataflow_path = None;
                self.dora_start_in_flight = false;
                self.dora_started = false;
                self.add_log(cx, &format!("[ERROR] [tts] {}", message));
                self.show_toast(
                    cx,
                    self.tr(
                        "Dora 启动失败，请查看日志",
                        "Dora startup failed. Please check logs",
                    ),
                );
            }
        }
    }

    fn maybe_retry_dataflow_start(&mut self, cx: &mut Cx) {
        if !self.dora_started {
            return;
        }
        if self.dora_start_in_flight {
            return;
        }
        if matches!(
            self.runtime_init_state,
            RuntimeInitState::Running | RuntimeInitState::Failed
        ) {
            return;
        }

        let is_running = self.dora.as_ref().map(|d| d.is_running()).unwrap_or(false);
        if is_running {
            return;
        }

        let should_retry = self
            .dora_start_attempt_at
            .map(|t| t.elapsed() >= Duration::from_secs(4))
            .unwrap_or(true);
        if should_retry {
            self.add_log(
                cx,
                "[WARN] [tts] Dora dataflow not running yet, retrying startup...",
            );
            self.dora_started = false;
        }
    }

    fn poll_dora_events(&mut self, cx: &mut Cx) {
        let events = self
            .dora
            .as_ref()
            .map(|d| d.poll_events())
            .unwrap_or_default();
        for event in events {
            match event {
                crate::dora_integration::DoraEvent::DataflowStarted { dataflow_id } => {
                    self.dora_start_in_flight = false;
                    self.add_log(
                        cx,
                        &format!("[INFO] [tts] Dora dataflow started: {}", dataflow_id),
                    );
                }
                crate::dora_integration::DoraEvent::DataflowStopped => {
                    self.dora_start_in_flight = false;
                    self.add_log(cx, "[WARN] [tts] Dora dataflow stopped");
                    self.dora_started = false;
                }
                crate::dora_integration::DoraEvent::Error { message } => {
                    self.dora_start_in_flight = false;
                    self.add_log(cx, &format!("[ERROR] [tts] Dora error: {}", message));
                    self.dora_started = false;
                    self.show_toast(
                        cx,
                        self.tr(
                            "Dora 启动失败，正在重试，请查看日志",
                            "Dora start failed; retrying. Please check logs",
                        ),
                    );
                }
                crate::dora_integration::DoraEvent::AsrTranscription { .. } => {}
            }
        }
    }

    fn poll_translation_dora_events(&mut self, cx: &mut Cx) {
        let events = self
            .translation_dora
            .as_ref()
            .map(|d| d.poll_events())
            .unwrap_or_default();

        for event in events {
            match event {
                crate::dora_integration::DoraEvent::DataflowStarted { dataflow_id } => {
                    self.add_translation_log(
                        cx,
                        &format!(
                            "[INFO] {}: {}",
                            self.tr("翻译数据流已启动", "Translation dataflow started"),
                            dataflow_id
                        ),
                    );
                }
                crate::dora_integration::DoraEvent::DataflowStopped => {
                    self.add_translation_log(
                        cx,
                        &format!(
                            "[WARN] {}",
                            self.tr("翻译数据流已停止", "Translation dataflow stopped")
                        ),
                    );
                    if self.translation_running {
                        let history_snapshot = self.translation_history_snapshot();
                        self.save_translation_transcript_on_stop(cx, &history_snapshot);
                    }
                    self.translation_running = false;
                    self.show_translation_running_panel(cx, false);
                    cx.stop_timer(self.translation_metrics_timer);
                    self.stop_translation_transcript_autosave_timer(cx);
                }
                crate::dora_integration::DoraEvent::Error { message } => {
                    self.add_translation_log(
                        cx,
                        &format!(
                            "[ERROR] {}: {}",
                            self.tr("翻译数据流错误", "Translation dataflow error"),
                            message
                        ),
                    );
                    if self.translation_running {
                        let history_snapshot = self.translation_history_snapshot();
                        self.save_translation_transcript_on_stop(cx, &history_snapshot);
                    }
                    self.translation_running = false;
                    self.show_translation_running_panel(cx, false);
                    cx.stop_timer(self.translation_metrics_timer);
                    self.stop_translation_transcript_autosave_timer(cx);
                }
                crate::dora_integration::DoraEvent::AsrTranscription { .. } => {}
            }
        }
    }

    fn is_qwen_backend(backend: &str) -> bool {
        backend == "qwen3_tts_mlx"
    }

    fn normalize_inference_backend(_raw: &str) -> &'static str {
        // Qwen3-only: always qwen3. See doc/REFACTOR_QWEN3_ONLY.md.
        "qwen3_tts_mlx"
    }

    fn normalize_zero_shot_backend(_raw: &str) -> &'static str {
        // Qwen3-only: always qwen3. See doc/REFACTOR_QWEN3_ONLY.md.
        "qwen3_tts_mlx"
    }

    fn absolutize_dataflow_paths(template_path: &Path, content: &str) -> String {
        let base_dir = template_path.parent().unwrap_or_else(|| Path::new("."));
        let mut output = String::with_capacity(content.len() + 256);
        let has_trailing_newline = content.ends_with('\n');

        for line in content.lines() {
            let trimmed = line.trim_start();
            let indent = &line[..line.len().saturating_sub(trimmed.len())];

            if let Some(raw_value) = trimmed.strip_prefix("path:") {
                let raw_value = raw_value.trim();

                let (path_value, quoted) = if raw_value.len() >= 2
                    && ((raw_value.starts_with('"') && raw_value.ends_with('"'))
                        || (raw_value.starts_with('\'') && raw_value.ends_with('\'')))
                {
                    (&raw_value[1..raw_value.len() - 1], true)
                } else {
                    (raw_value, false)
                };

                let should_resolve = path_value != "dynamic"
                    && !path_value.starts_with('/')
                    && path_value.contains('/');

                if should_resolve {
                    let candidate = base_dir.join(path_value);
                    if candidate.exists() {
                        let resolved = candidate.canonicalize().unwrap_or(candidate);
                        if quoted {
                            output.push_str(&format!("{indent}path: \"{}\"\n", resolved.display()));
                        } else {
                            output.push_str(&format!("{indent}path: {}\n", resolved.display()));
                        }
                        continue;
                    }
                }
            }

            output.push_str(line);
            output.push('\n');
        }

        if !has_trailing_newline && output.ends_with('\n') {
            output.pop();
        }
        output
    }

    fn resolve_dataflow_template_path(&self) -> PathBuf {
        let env_path = std::env::var("MOXIN_DATAFLOW_PATH")
            .ok()
            .map(PathBuf::from)
            .filter(|p| p.exists());
        if let Some(path) = env_path {
            return path;
        }

        let app_resources = std::env::var("MOXIN_APP_RESOURCES")
            .ok()
            .map(PathBuf::from)
            .filter(|p| p.exists());
        if let Some(resources) = app_resources {
            let bundle_dataflow = resources.join("dataflow").join("tts.yml");
            if bundle_dataflow.exists() {
                return bundle_dataflow;
            }
        }

        PathBuf::from("apps/moxin-voice/dataflow/tts.yml")
    }

    fn materialize_runtime_dataflow(&mut self, cx: &mut Cx) -> Result<PathBuf, String> {
        let template_path = self.resolve_dataflow_template_path();
        let template = fs::read_to_string(&template_path)
            .map_err(|e| format!("read template failed ({}): {}", template_path.display(), e))?;

        let inference_backend =
            Self::normalize_inference_backend(&self.app_preferences.inference_backend).to_string();
        let zero_shot_backend =
            Self::normalize_zero_shot_backend(&self.app_preferences.zero_shot_backend).to_string();
        std::env::set_var("MOXIN_INFERENCE_BACKEND", &inference_backend);
        std::env::set_var("MOXIN_ZERO_SHOT_BACKEND", &zero_shot_backend);
        let asr_bin = Self::resolve_dora_binary("dora-qwen3-asr")
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|| {
                self.add_log(
                    cx,
                    "[WARN] [tts] dora-qwen3-asr binary not found — run: cargo build --release -p dora-qwen3-asr",
                );
                String::new()
            });
        let qwen_tts_bin = Self::resolve_dora_binary("qwen-tts-node")
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|| {
                self.add_log(
                    cx,
                    "[WARN] [tts] qwen-tts-node binary not found — run: cargo build --release -p dora-qwen3-tts-mlx",
                );
                String::new()
            });

        let rendered = template
            .replace("__MOXIN_INFERENCE_BACKEND__", &inference_backend)
            .replace("__MOXIN_ZERO_SHOT_BACKEND__", &zero_shot_backend)
            .replace("__ASR_BIN_PATH__", &asr_bin)
            .replace("__QWEN_TTS_BIN_PATH__", &qwen_tts_bin);
        let rendered = Self::absolutize_dataflow_paths(&template_path, &rendered);

        let runtime_dir = dirs::home_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join(".dora")
            .join("runtime")
            .join("dataflow");
        fs::create_dir_all(&runtime_dir)
            .map_err(|e| format!("create runtime dataflow dir failed: {}", e))?;
        let runtime_path = runtime_dir.join("tts.runtime.yml");
        fs::write(&runtime_path, rendered)
            .map_err(|e| format!("write runtime dataflow failed: {}", e))?;

        self.add_log(
            cx,
            &format!(
                "[INFO] [tts] Runtime dataflow prepared: {} (inference={}, zero_shot={})",
                runtime_path.display(),
                inference_backend,
                zero_shot_backend
            ),
        );
        Ok(runtime_path)
    }

    fn resolve_translation_dataflow_template_path(&self) -> Option<PathBuf> {
        let env_path = std::env::var("MOXIN_TRANSLATION_DATAFLOW_PATH")
            .ok()
            .map(PathBuf::from)
            .filter(|p| p.exists());
        if env_path.is_some() {
            return env_path;
        }

        let app_resources = std::env::var("MOXIN_APP_RESOURCES")
            .ok()
            .map(PathBuf::from)
            .filter(|p| p.exists());
        if let Some(resources) = app_resources {
            let bundle_dataflow = resources.join("dataflow").join("translation_qwen35.yml");
            if bundle_dataflow.exists() {
                return Some(bundle_dataflow);
            }
        }

        [
            PathBuf::from("apps/moxin-voice/dataflow/translation_qwen35.yml"),
            dirs::home_dir()
                .unwrap_or_default()
                .join(".OminiX/dataflows/translation_qwen35.yml"),
        ]
        .into_iter()
        .find(|p| p.exists())
    }

    fn stop_dora(&mut self, cx: &mut Cx) {
        if self.dora.is_none() {
            return;
        }

        self.add_log(cx, "[INFO] [tts] Stopping TTS dataflow...");

        if let Some(dora) = &mut self.dora {
            dora.stop_dataflow();
        }
        self.dora_started = false;
        self.dora_start_in_flight = false;
        self.dora_start_attempt_at = None;
        self.dora_start_rx = None;
        self.dora_pending_dataflow_path = None;

        self.add_log(cx, "[INFO] [tts] Dataflow stopped");
    }

    // ── Translation helpers ───────────────────────────────────────────────────

    /// Toggle the translation overlay on/off.
    ///
    /// When activating:
    ///   1. Materialises `translation_qwen35.yml` with src/tgt lang env placeholders replaced
    ///   2. Starts a separate Dora dataflow for the translation pipeline
    ///   3. Sets `SharedDoraState.translation_window_visible = true` so `app.rs` shows the window
    ///
    /// When deactivating: stops the translation dataflow and hides the window.
    /// Start the translation dataflow and switch the translation page to running view.
    fn start_translation_dataflow(&mut self, cx: &mut Cx) {
        Self::ensure_bundle_bin_on_path();

        // Pause TTS dataflow to free the ASR process before starting translation.
        if self.dora_started {
            self.tts_paused_for_translation = true;
            self.stop_dora(cx);
            self.add_translation_log(
                cx,
                &format!(
                    "[INFO] {}",
                    self.tr("已暂停 TTS 数据流", "TTS dataflow paused")
                ),
            );
        }

        self.add_translation_log(
            cx,
            &format!(
                "[INFO] {}...",
                self.tr("正在启动翻译数据流", "Starting translation dataflow")
            ),
        );

        let template_path = match self.resolve_translation_dataflow_template_path() {
            Some(p) => p,
            None => {
                self.add_translation_log(
                    cx,
                    &format!(
                        "[ERROR] {}",
                        self.tr(
                            "未找到 translation_qwen35.yml",
                            "translation_qwen35.yml not found"
                        )
                    ),
                );
                return;
            }
        };

        // Read template and substitute language placeholders
        let template_content = match std::fs::read_to_string(&template_path) {
            Ok(s) => s,
            Err(e) => {
                self.add_translation_log(
                    cx,
                    &format!(
                        "[ERROR] {}: {}",
                        self.tr("读取模板失败", "Failed to read template"),
                        e
                    ),
                );
                return;
            }
        };

        let src_upper = self.translation_src_lang.to_uppercase();
        let tgt_upper = self.translation_tgt_lang.to_uppercase();

        // Endpoint detection policy (language-aware):
        // - start/end frame hysteresis
        // - minimum segment duration gate
        // - start/end RMS hysteresis
        let (
            speech_start_frames,
            speech_end_frames,
            speech_end_ms,
            question_end_silence_ms,
            min_segment_ms,
            start_rms_threshold,
            end_rms_threshold,
        ) = match self.translation_src_lang.as_str() {
            // Chinese: lower endpoint/min-segment latency while preserving stability.
            "zh" => (
                5_i32, 10_i32, 420_i32, 1200_i32, 420_i32, 0.018_f32, 0.010_f32,
            ),
            "en" => (
                4_i32, 30_i32, 300_i32, 900_i32, 300_i32, 0.015_f32, 0.009_f32,
            ),
            "fr" => (
                4_i32, 10_i32, 320_i32, 1000_i32, 320_i32, 0.016_f32, 0.009_f32,
            ),
            _ => (
                4_i32, 10_i32, 320_i32, 1000_i32, 320_i32, 0.016_f32, 0.009_f32,
            ),
        };
        let max_segment_ms = 8000_i32;

        // System audio (ScreenCaptureKit) has a much cleaner signal than a microphone:
        // no breath noise, no room echo, no handling noise.  Use lower RMS thresholds
        // so quiet speech / video audio isn't gated out by the VAD.
        let is_system_audio = self.translation_device_idx == 0;
        let (start_rms_threshold, end_rms_threshold) = if is_system_audio {
            (start_rms_threshold * 0.3, end_rms_threshold * 0.3)
        } else {
            (start_rms_threshold, end_rms_threshold)
        };

        // Resolve absolute binary paths for dev (target/release or target/debug)
        // and DMG distribution (binary sibling to current_exe).
        let asr_path = Self::resolve_dora_binary("dora-qwen3-asr")
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|| {
                self.add_translation_log(cx, "[WARN] dora-qwen3-asr binary not found — run: cargo build --release -p dora-qwen3-asr");
                String::new()
            });
        let translator_path = Self::resolve_dora_binary("dora-qwen35-translator")
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_else(|| {
                self.add_translation_log(cx, "[WARN] dora-qwen35-translator binary not found — run: cargo build --release -p dora-qwen35-translator");
                String::new()
            });

        let passthrough_flag = if self.translation_tgt_lang == "none" {
            "1"
        } else {
            "0"
        };
        let rendered = template_content
            .replace("__TRANSLATION_SRC_LANG__", &self.translation_src_lang)
            .replace("__TRANSLATION_TGT_LANG__", &self.translation_tgt_lang)
            .replace("__TRANSLATOR_PASSTHROUGH__", passthrough_flag)
            .replace("__ASR_BIN_PATH__", &asr_path)
            .replace("__TRANSLATOR_BIN_PATH__", &translator_path)
            .replace("__SPEECH_START_FRAMES__", &speech_start_frames.to_string())
            .replace("__SPEECH_END_FRAMES__", &speech_end_frames.to_string())
            .replace("__SPEECH_END_MS__", &speech_end_ms.to_string())
            .replace(
                "__QUESTION_END_SILENCE_MS__",
                &question_end_silence_ms.to_string(),
            )
            .replace("__MIN_SEGMENT_MS__", &min_segment_ms.to_string())
            .replace("__MAX_SEGMENT_MS__", &max_segment_ms.to_string())
            .replace(
                "__START_RMS_THRESHOLD__",
                &format!("{:.4}", start_rms_threshold),
            )
            .replace(
                "__END_RMS_THRESHOLD__",
                &format!("{:.4}", end_rms_threshold),
            );
        let rendered = Self::absolutize_dataflow_paths(&template_path, &rendered);

        // Write rendered dataflow to a temp file
        let tmp_path = std::env::temp_dir().join("moxin_translation_dataflow.yml");
        if let Err(e) = std::fs::write(&tmp_path, &rendered) {
            self.add_translation_log(
                cx,
                &format!(
                    "[ERROR] {}: {}",
                    self.tr("写入临时文件失败", "Failed to write temp file"),
                    e
                ),
            );
            return;
        }

        if self.translation_dora.is_none() {
            self.translation_dora = Some(DoraIntegration::new());
        }

        let started = self
            .translation_dora
            .as_ref()
            .map(|d| d.start_dataflow(tmp_path))
            .unwrap_or(false);
        if !started {
            self.add_translation_log(
                cx,
                &format!(
                    "[ERROR] {}",
                    self.tr(
                        "启动失败：未能提交翻译数据流启动命令",
                        "Failed to start: could not submit translation dataflow command"
                    )
                ),
            );
            return;
        }
        let pair_suffix = if self.translation_tgt_lang == "none" {
            format!("{} · {}", src_upper, self.tr("不翻译", "passthrough"))
        } else {
            format!("{} → {}", src_upper, tgt_upper)
        };
        self.add_translation_log(
            cx,
            &format!(
                "[INFO] {} ({})",
                self.tr("数据流启动命令已提交", "Dataflow start command submitted"),
                pair_suffix,
            ),
        );
        self.add_translation_log(
            cx,
            &format!(
                "[INFO] {}: start={}f, end={}ms ({}f), min_segment={}ms, question_end={}ms, max_segment={}ms, rms(start/end)={:.4}/{:.4}",
                self.tr("VAD 策略", "VAD policy"),
                speech_start_frames,
                speech_end_ms,
                speech_end_frames,
                min_segment_ms,
                question_end_silence_ms,
                max_segment_ms,
                start_rms_threshold,
                end_rms_threshold
            ),
        );

        // Show the translation overlay window via SharedDoraState
        if let Some(shared) = self.translation_shared_state() {
            shared.translation_locale_en.set(self.is_english());
            shared.translation_lang_pair.set((
                self.translation_src_lang.clone(),
                self.translation_tgt_lang.clone(),
            ));
            shared
                .translation_font_size_preset
                .set(self.translation_overlay_font_size_preset.clone());
            shared
                .translation_footer_font_size_preset
                .set(self.translation_overlay_footer_font_size_preset.clone());
            shared
                .translation_anchor_position_preset
                .set(self.translation_overlay_anchor_position_preset.clone());
            // Clear any previous translation text before showing the overlay so a
            // restart starts with an empty board even if the window was kept open.
            shared.translation.set(None);
            // Mark window visible. Single set() is enough — DirtyValue still flags
            // dirty even when value matches, and the previous false→true flicker
            // could cause the overlay window to minimize-then-restore.
            shared.translation_window_visible.set(true);
            // Do NOT re-push translation_overlay_fullscreen here — it would
            // trigger a resize back to the preset dimensions, discarding any
            // manual resize the user performed between runs.
            shared
                .translation_overlay_opacity
                .set(self.translation_overlay_opacity);
            // Reset status to warming until the bridges report ready.
            shared.translation_overlay_active.set(true);
            shared.translation_overlay_status.set("warming".to_string());
        }
        // Sync audio source from current dropdown selection
        self.send_audio_source_to_bridge(self.translation_device_idx == 0);

        // Switch to running view
        self.translation_running = true;
        self.translation_transcript_autosave_cursor = 0;
        self.show_translation_running_panel(cx, true);

        // Start metrics polling timer (1s interval)
        self.translation_metrics_timer = cx.start_interval(1.0);
        self.sync_translation_transcript_autosave_timer(cx);
    }

    /// Stop the translation dataflow and return to settings view.
    fn stop_translation_dataflow(&mut self, cx: &mut Cx) {
        self.add_translation_log(
            cx,
            &format!(
                "[INFO] {}...",
                self.tr("正在停止翻译", "Stopping translation")
            ),
        );

        // Capture translation history before clearing shared state.
        let history_snapshot = self.translation_history_snapshot();

        // Keep the overlay window open — only clear the translation data.
        // The window stays visible until the user closes it manually.
        if let Some(shared) = self.translation_shared_state() {
            shared.translation.set(None);
            shared.translation_overlay_active.set(false);
            shared.translation_overlay_status.set("idle".to_string());
        }

        self.save_translation_transcript_on_stop(cx, &history_snapshot);

        if let Some(dora) = &self.translation_dora {
            let _ = dora.stop_dataflow();
        }

        self.translation_running = false;
        self.show_translation_running_panel(cx, false);
        self.translation_last_logged_fingerprint = None;

        // Stop metrics timer
        cx.stop_timer(self.translation_metrics_timer);
        self.stop_translation_transcript_autosave_timer(cx);

        // Resume TTS dataflow if it was paused for translation.
        if self.tts_paused_for_translation {
            self.tts_paused_for_translation = false;
            // dora_started is already false after stop_dora; clearing the pause flag
            // lets the event-loop auto-start block restart TTS on the next tick.
            self.add_log(
                cx,
                "[INFO] [tts] Resuming TTS dataflow after translation stop...",
            );
        }
    }

    fn save_translation_transcript_on_stop(
        &mut self,
        cx: &mut Cx,
        history_snapshot: &[(String, String)],
    ) {
        if history_snapshot.is_empty() {
            return;
        }

        if self.app_preferences.translation_periodic_save_transcript {
            self.save_translation_transcript_autosave_batch(cx, history_snapshot, true);
            return;
        }

        if !self.app_preferences.translation_auto_save_transcript {
            return;
        }

        let save_path = self.transcript_save_path_from_preferences();
        self.save_translation_transcript_snapshot(cx, history_snapshot, save_path, 1, true);
    }

    fn autosave_translation_transcript(&mut self, cx: &mut Cx) {
        if !self.app_preferences.translation_periodic_save_transcript {
            return;
        }
        let history_snapshot = self.translation_history_snapshot();
        self.save_translation_transcript_autosave_batch(cx, &history_snapshot, false);
    }

    fn save_translation_transcript_autosave_batch(
        &mut self,
        cx: &mut Cx,
        history_snapshot: &[(String, String)],
        show_toast: bool,
    ) {
        let start = self
            .translation_transcript_autosave_cursor
            .min(history_snapshot.len());
        if start >= history_snapshot.len() {
            return;
        }
        let entries = &history_snapshot[start..];
        let save_path = self.transcript_timestamped_save_path_from_preferences();
        let first_index = start + 1;
        if self.save_translation_transcript_snapshot(cx, entries, save_path, first_index, show_toast)
        {
            self.translation_transcript_autosave_cursor = history_snapshot.len();
        }
    }

    fn save_translation_transcript_snapshot(
        &mut self,
        cx: &mut Cx,
        history_snapshot: &[(String, String)],
        save_path: PathBuf,
        first_index: usize,
        show_toast: bool,
    ) -> bool {
        match crate::transcript_export::save_direct_with_start_index(
            &save_path,
            history_snapshot,
            &self.translation_src_lang,
            &self.translation_tgt_lang,
            first_index,
        ) {
            Ok(()) => {
                self.add_translation_log(
                    cx,
                    &format!(
                        "[INFO] {}: {}",
                        self.tr("Transcript 已保存", "Transcript saved"),
                        save_path.display()
                    ),
                );
                if show_toast {
                    self.show_toast(
                        cx,
                        &format!(
                            "{} {}",
                            self.tr("Transcript 已保存：", "Transcript saved:"),
                            save_path
                                .file_name()
                                .and_then(|name| name.to_str())
                                .unwrap_or("transcript.md")
                        ),
                    );
                }
                true
            }
            Err(err) => {
                self.add_translation_log(
                    cx,
                    &format!(
                        "[ERROR] {}: {}",
                        self.tr("保存 Transcript 失败", "Failed to save transcript"),
                        err
                    ),
                );
                if show_toast {
                    self.show_toast(cx, self.tr("保存 Transcript 失败", "Failed to save transcript"));
                }
                false
            }
        }
    }

    fn sync_translation_transcript_autosave_timer(&mut self, cx: &mut Cx) {
        self.stop_translation_transcript_autosave_timer(cx);
        if self.translation_running && self.app_preferences.translation_periodic_save_transcript {
            self.translation_transcript_autosave_timer = cx.start_interval(60.0);
        }
    }

    fn stop_translation_transcript_autosave_timer(&mut self, cx: &mut Cx) {
        cx.stop_timer(self.translation_transcript_autosave_timer);
        self.translation_transcript_autosave_timer = Timer::default();
    }

    /// Poll translation updates and mirror completed entries to the log.
    fn poll_translation_metrics(&mut self, cx: &mut Cx) {
        // Read translation status from shared state
        if let Some(shared) = self.translation_shared_state() {
            let translation_snapshot = shared.translation.read();
            if let Some(update) = translation_snapshot {
                // Mirror newly arrived translation to the log WITHOUT consuming dirty flag.
                let fingerprint = format!(
                    "h{}|p={}",
                    update.history.len(),
                    update.pending_source_text.len()
                );
                let should_log = self
                    .translation_last_logged_fingerprint
                    .as_ref()
                    .map(|last| last != &fingerprint)
                    .unwrap_or(true);

                if should_log {
                    if let Some(last) = update.history.last() {
                        let msg = format!(
                            "[{}] {} → {}",
                            self.tr("翻译完成", "Translated"),
                            last.source_text,
                            last.translation
                        );
                        self.add_translation_log(cx, &msg);
                    }
                    self.translation_last_logged_fingerprint = Some(fingerprint);
                }
            }
        }
    }

    /// Toggle which panel is visible in the translation page body.
    fn show_translation_running_panel(&mut self, cx: &mut Cx, running: bool) {
        // Status badge in page header
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .translation_page
                    .page_header
                    .translation_status_badge
            ))
            .set_visible(cx, running);

        // Settings panel stays visible the whole time; nothing else in the body
        // toggles with the running state now that the runtime-logs area is gone.
        self.update_translation_action_button(cx);
        self.update_translation_locked_controls(cx, running);

        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .translation_page
            ))
            .redraw(cx);
    }

    /// Disable the dropdowns whose value is locked while a translation dataflow
    /// is running (input source, source language, target language).
    ///
    /// Two layers of locking:
    ///   1. Shader `disabled` instance fades the bg/text so the control reads
    ///      visually as disabled.
    ///   2. The DropDown's built-in `disabled` animator state is toggled, which
    ///      the widget's `Hit::FingerDown` handler checks before opening the
    ///      popup — so clicks on a disabled dropdown are silently swallowed.
    fn update_translation_locked_controls(&mut self, cx: &mut Cx, running: bool) {
        let disabled: f32 = if running { 1.0 } else { 0.0 };
        let animator_state: &[LiveId; 2] = if running {
            ids!(disabled.on)
        } else {
            ids!(disabled.off)
        };
        let paths = [
            ids!(content_wrapper.main_content.left_column.content_area.translation_page.translation_body.translation_settings_panel.settings_card.setting_row_source.translation_source_dropdown),
            ids!(content_wrapper.main_content.left_column.content_area.translation_page.translation_body.translation_settings_panel.settings_card.setting_row_src_lang.src_lang_dropdown),
            ids!(content_wrapper.main_content.left_column.content_area.translation_page.translation_body.translation_settings_panel.settings_card.setting_row_tgt_lang.tgt_lang_dropdown),
        ];
        for path in paths {
            let dd = self.view.drop_down(path);
            dd.apply_over(cx, live! {
                draw_bg: { disabled: (disabled) }
                draw_text: { disabled: (disabled) }
            });
            if let Some(mut inner) = dd.borrow_mut() {
                inner.animator_play(cx, animator_state);
            };
        }
    }

    /// Update the single Start/Stop action button (text + color) based on the
    /// current running state and active locale.
    fn update_translation_action_button(&mut self, cx: &mut Cx) {
        let label = if self.translation_running {
            self.tr("停止翻译", "Stop Translation")
        } else {
            self.tr("启动实时翻译", "Start Live Translation")
        };
        let btn = self.view.button(ids!(
            content_wrapper
                .main_content
                .left_column
                .content_area
                .translation_page
                .translation_body
                .translation_action_btn
        ));
        btn.set_text(cx, label);
        let running_flag: f32 = if self.translation_running { 1.0 } else { 0.0 };
        btn.apply_over(cx, live! { draw_bg: { running: (running_flag) } });
    }

    /// Append a line to the translation page log and refresh the label.
    // No-op: the in-page translation log Label was removed because every line
    // change forced Makepad's text layouter to allocate a new LaidoutText that
    // its LRU cache could not release (Rcs retained externally), leaking memory
    // proportional to session length. Call sites are preserved to keep diagnostic
    // log lines flowing to tracing/stderr without touching the UI.
    fn add_translation_log(&mut self, _cx: &mut Cx, line: &str) {
        ::log::info!("[translation] {line}");
    }

