    /// Probe screen-recording permission early so the macOS dialog appears before Start.
    fn ensure_translation_permission_probe(&mut self, cx: &mut Cx) {
        if !should_probe_translation_permission_on_page_entry(
            self.current_page,
            self.translation_permission_probed,
        ) {
            return;
        }

        self.translation_permission_probed = true;

        #[cfg(target_os = "macos")]
        {
            moxin_dora_bridge::widgets::probe_permission_async();
            // Check probe result after 2 s and show/hide the restart hint.
            self.translation_permission_timer = cx.start_timeout(2.0);
        }

        #[cfg(not(target_os = "macos"))]
        {
            let _ = cx;
        }
    }

    /// Populate the translation input device dropdown with available CPAL devices.
    fn populate_translation_input_dropdown(&mut self, cx: &mut Cx) {
        use cpal::traits::{DeviceTrait, HostTrait};

        let host = cpal::default_host();
        let mut names: Vec<String> = Vec::new();
        if let Ok(devs) = host.input_devices() {
            for d in devs {
                if let Ok(name) = d.name() {
                    if !names.contains(&name) {
                        names.push(name);
                    }
                }
            }
        }
        self.translation_audio_devices = names;

        // Index 0 = System Audio, 1 = System Default Mic, 2..N = CPAL devices
        let mut labels = vec![
            self.tr("系统音频", "System Audio").to_string(),
            self.tr("系统默认麦克风", "System Default Microphone")
                .to_string(),
        ];
        labels.extend(self.translation_audio_devices.clone());

        self.view
            .drop_down(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .translation_page
                    .translation_body
                    .translation_settings_panel
                    .settings_card
                    .setting_row_source
                    .translation_source_dropdown
            ))
            .set_labels(cx, labels);
        let total = self.translation_audio_devices.len() + 2;
        let selected_idx = self.translation_device_idx.min(total.saturating_sub(1));
        self.view
            .drop_down(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .translation_page
                    .translation_body
                    .translation_settings_panel
                    .settings_card
                    .setting_row_source
                    .translation_source_dropdown
            ))
            .set_selected_item(cx, selected_idx);
    }

