    fn sync_selected_model_ui(&mut self, cx: &mut Cx) {
        // Qwen3-only: hide model picker row — no backend choice available.
        self.view
            .view(ids!(
                content_wrapper
                    .main_content
                    .left_column
                    .content_area
                    .tts_page
                    .cards_container
                    .input_section
                    .input_content
                    .bottom_bar
                    .model_row
            ))
            .set_visible(cx, false);

        if self.model_options.is_empty() {
            self.selected_tts_model_id = None;
            self.view
                .button(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                    .bottom_bar
                        .model_row
                        .model_picker_btn
                ))
                .set_text(cx, self.tr("🔮 暂无可用模型", "🔮 No model available"));
            return;
        }

        let selected_model = self
            .selected_tts_model_id
            .as_ref()
            .and_then(|id| self.model_options.iter().find(|m| &m.id == id))
            .cloned()
            .or_else(|| self.model_options.first().cloned());

        if let Some(model) = selected_model {
            self.selected_tts_model_id = Some(model.id.clone());
            self.view
                .button(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .input_section
                        .input_content
                    .bottom_bar
                        .model_row
                        .model_picker_btn
                ))
                .set_text(cx, &format!("🔮 {}", model.name));
        }
    }

