impl TTSScreenRef {
    pub fn translation_shared_dora_state(&self) -> Option<Arc<moxin_dora_bridge::SharedDoraState>> {
        self.borrow()
            .and_then(|inner| inner.translation_shared_state())
    }

    pub fn stop_translation_from_overlay(&self, cx: &mut Cx) {
        if let Some(mut inner) = self.borrow_mut() {
            if inner.translation_running {
                inner.stop_translation_dataflow(cx);
            }
        }
    }

    pub fn update_dark_mode(&self, cx: &mut Cx, dark_mode: f64) {
        if let Some(mut inner) = self.borrow_mut() {
            inner.dark_mode = dark_mode;
            inner.apply_dark_mode(cx);

            // Apply dark mode to voice selector
            inner
                .view
                .voice_selector(ids!(
                    content_wrapper
                        .main_content
                        .left_column
                        .content_area
                        .tts_page
                        .cards_container
                        .controls_panel
                        .settings_panel
                        .voice_section
                        .voice_selector
                ))
                .update_dark_mode(cx, dark_mode);

            // Apply dark mode to log markdown
            let log_markdown = inner.view.markdown(ids!(
                content_wrapper
                    .main_content
                    .log_section
                    .log_content_column
                    .log_scroll
                    .log_content_wrapper
                    .log_content
            ));
            log_markdown.apply_over(
                cx,
                live! {
                    draw_normal: { dark_mode: (dark_mode) }
                    draw_bold: { dark_mode: (dark_mode) }
                },
            );

            // Apply dark mode to voice clone modal
            inner
                .view
                .voice_clone_modal(ids!(voice_clone_modal))
                .update_dark_mode(cx, dark_mode);

            inner.view.redraw(cx);
        }
    }

    /// Stop all Dora dataflows and join their worker threads synchronously.
    /// Must be called from the app shutdown handler before the process exits,
    /// because std::process::exit() skips destructors and leaves orphan Python nodes.
    pub fn shutdown_cleanup(&self) {
        if let Some(mut inner) = self.borrow_mut() {
            // Dropping DoraIntegration sends the stop signal and joins the worker
            // thread, which calls `dora stop <id>` before returning.
            drop(inner.translation_dora.take());
            drop(inner.dora.take());

            // A stopped dataflow can still leave Dora-managed node processes behind
            // on some machines. Reset the Dora runtime on shutdown so packaged nodes
            // like dora-qwen35-translator do not remain alive after the app exits.
            TTSScreen::ensure_bundle_bin_on_path();
            let startup_lock_path = TTSScreen::dora_startup_lock_path();
            match DoraStartupLockGuard::acquire(startup_lock_path, Duration::from_secs(5)) {
                Ok(_lock) => match Command::new("dora").arg("destroy").status() {
                    Ok(status) if status.success() => {
                        ::log::info!("Dora runtime destroyed during app shutdown");
                    }
                    Ok(status) => {
                        ::log::warn!(
                            "`dora destroy` exited with status {} during shutdown",
                            status
                        );
                    }
                    Err(err) => {
                        ::log::warn!("Failed to run `dora destroy` during shutdown: {}", err);
                    }
                },
                Err(err) => {
                    ::log::warn!(
                        "Failed to acquire Dora startup lock during shutdown: {}",
                        err
                    );
                }
            }
        }
    }
}

fn runtime_init_progress_for_display_value(progress: f64, _status: &str) -> f64 {
    progress.clamp(0.0, 1.0)
}

fn runtime_init_next_display_progress(current: f64, incoming: f64) -> f64 {
    current.clamp(0.0, 1.0).max(incoming.clamp(0.0, 1.0))
}

